INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('de07acc1-b2e2-57be-a562-ff6cdd1ebde1'::uuid, 'b8a78273-13b1-5e59-8396-bfff0f119e5f'::uuid, 1, '浙江适用杂草：稗（稗草）', '{"kind":"weed","item_id":"zj-weed-r2","weed_name":"稗（稗草）","canonical_name":"稗","scientific_name":"Echinochloa crus-galli","family_genus":"禾本科·稗属","companion_crops":["水稻","旱稻","玉米","大豆","花生","蔬菜","棉花"],"distribution_note":"全国各稻区","distribution_provinces":["黑龙江","吉林","辽宁","江苏","浙江","安徽","江西","湖北","湖南","广东","广西","福建","海南","四川","重庆","贵州","云南","河南南部","陕西南部","台湾"],"growth_stages_text":"① 幼苗期（1～3叶）：胚芽鞘出土后第一片真叶细长，叶片浅绿平滑无毛；② 分蘖期（4～6叶）：基部开始分蘖，株高10～20cm，茎扁圆、基部略带紫红；③ 拔节抽穗期：株高可达60～120cm，圆锥花序松散下垂、分枝有芒，呈紫绿色；④ 灌浆成熟期：种子卵形、光滑发亮，成熟后易脱落，单株可结籽数千至上万粒。","best_control_stage_text":"1～3叶期（幼苗期），此时根系未扎深、抗药力最弱；水稻直播田在稗草2～3叶期防效最佳，超过5叶需大幅加量且易产生药害。","spray_window_text":"直播稻田播后2～4天封闭处理，或稗草2～3叶期茎叶喷雾；移栽稻田移栽后5～7天；旱田在播后苗前土壤处理或苗后早期。","identification_key_text":"与水稻最易混淆，区别在于：稗草无叶耳叶舌、叶片较宽软、基部常带紫红色、根系无沼泽通气组织；水稻有叶耳叶舌、叶片直立、有明显中脉。稗草根系较浅、易整株拔起，水稻根系深扎不易拔出。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":2,"cell_range":"A2:I2","row_sha256":"a9cad91ef361b96d3b0f89a01226963b0c29167d92bbf807177ac7ab34708122","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=2;cells=A2:I2"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_corn","crop_soybean"]'::jsonb, '["species_barnyardgrass"]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('cea147cc-b067-5099-862d-95e320da61f9'::uuid, 'c52f13cc-94fc-52e9-b84a-cf86d4296db6'::uuid, 1, '浙江适用杂草：无芒稗', '{"kind":"weed","item_id":"zj-weed-r3","weed_name":"无芒稗","canonical_name":"无芒稗","scientific_name":"Echinochloa crus-galli var. mitis","family_genus":"禾本科·稗属","companion_crops":["水稻","旱稻","玉米","大豆","蔬菜"],"distribution_note":"","distribution_provinces":["黑龙江","吉林","辽宁","江苏","浙江","安徽","江西","湖北","湖南","广东","广西","四川","云南","河南","台湾"],"growth_stages_text":"① 幼苗期：与稗相似但叶色略深、叶鞘带紫；② 分蘖期：分蘖力强于稗，丛生、抗逆性强；③ 抽穗期：圆锥花序较紧密、小穗无芒或芒极短，是与稗最明显的区别；④ 成熟期：种子较小、褐色，落粒性更强。","best_control_stage_text":"2～4叶期。分蘖后再生能力极强，一旦进入分蘖期防效显著下降。","spray_window_text":"与稗草同期防治：播后封闭或2～4叶期茎叶处理，注意分蘖前完成。","identification_key_text":"花序无芒或芒长不足稗草的1/3，小穗排列紧密、紫褐色；植株比稗更粗壮、分蘖更多、抗药性强，同一田块常比稗晚发但长势更旺。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":3,"cell_range":"A3:I3","row_sha256":"f10e9049b865d6ed24b087de0968c834b86dfa912680072a69d6d811ad441355","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=3;cells=A3:I3"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('53b3228e-070c-5f4c-a8e9-829d783e4402'::uuid, 'f8075e97-75c9-54ba-9ee3-5e34811c9de6'::uuid, 1, '浙江适用杂草：西来稗', '{"kind":"weed","item_id":"zj-weed-r4","weed_name":"西来稗","canonical_name":"西来稗","scientific_name":"Echinochloa crus-galli var. zelayensis","family_genus":"禾本科·稗属","companion_crops":["水稻","玉米","大豆","棉花","蔬菜"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","广东","广西","福建","四川","云南","河南","陕西","台湾"],"growth_stages_text":"① 幼苗期：叶片较窄、直立，基部暗紫；② 分蘖期：丛生型，株型较矮壮；③ 抽穗期：圆锥花序直立或微弯，小穗具短芒、排列密集；④ 成熟期：种子成熟整齐，落粒集中。","best_control_stage_text":"2～3叶期，与稗草同步；因株型矮壮、基部坚硬，大龄后极难防除。","spray_window_text":"与稗草同期：封闭处理或苗后2～3叶期；旱田在苗后早期。","identification_key_text":"花序直立、小穗密集、芒短而硬；植株基部暗紫色明显，叶鞘常带紫晕，株高比稗草矮10～20cm，抗倒伏强。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":4,"cell_range":"A4:I4","row_sha256":"8e93774f9705613fa4f28184fb619cc442e60fc5b0acad4782ad377b6115526d","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=4;cells=A4:I4"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('2a753f85-6dbd-54f3-85fd-257819663489'::uuid, '83d7a9be-7bd5-5ddb-b1c2-62d7c3742bcb'::uuid, 1, '浙江适用杂草：光头稗', '{"kind":"weed","item_id":"zj-weed-r6","weed_name":"光头稗","canonical_name":"光头稗","scientific_name":"Echinochloa colona","family_genus":"禾本科·稗属","companion_crops":["水稻","棉花","大豆","蔬菜","甘蔗"],"distribution_note":"","distribution_provinces":["广东","广西","福建","海南","云南","江西","湖南","湖北","江苏","浙江","四川","台湾"],"growth_stages_text":"① 幼苗期：叶片短而宽、浅灰绿；② 分蘖期：分蘖多、丛生贴地；③ 抽穗期：圆锥花序窄小、小穗排列成规则两行、无芒，故称「光头」；④ 成熟期：种子极小、数量多。","best_control_stage_text":"2～3叶期。植株矮小但分蘖力极强，一旦进入分蘖丛生阶段需多次施药。","spray_window_text":"播后封闭处理或苗后早期（2～3叶）茎叶喷雾；南方棉田、甘蔗田注意在分蘖前完成。","identification_key_text":"小穗沿花序轴排成整齐的两行、无芒、花序窄细如「光头」；植株矮小、贴地丛生、叶片灰绿色，与稗草直立大型株型明显不同。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":6,"cell_range":"A6:I6","row_sha256":"f93240cafd688829ef15bdc3eb91457eddb89a6404bbfb4931676d95e9051d4f","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=6;cells=A6:I6"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('c79ee0a3-788b-5aa9-99a5-43f44be2d883'::uuid, 'f8e98caf-fa8c-593a-a1c5-481c920a66a5'::uuid, 1, '浙江适用杂草：千金子', '{"kind":"weed","item_id":"zj-weed-r7","weed_name":"千金子","canonical_name":"千金子","scientific_name":"Leptochloa chinensis","family_genus":"禾本科·千金子属","companion_crops":["水稻","旱稻","棉花","大豆","蔬菜"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","广东","广西","福建","海南","四川","重庆","云南","河南南部","台湾"],"growth_stages_text":"① 幼苗期：叶片纤细柔软、浅绿；② 分蘖期：基部丛生、分蘖极多，匍匐后斜升，节上可生根；③ 抽穗期：圆锥花序开展、小穗细小密集呈灰紫色，株高30～70cm；④ 成熟期：种子极小、千粒重极低，随水传播。","best_control_stage_text":"2～4叶期。千金子在直播稻田抽穗极早（播后30天即可抽穗），一旦抽穗种子迅速成熟，必须抢在抽穗前防除。","spray_window_text":"直播稻播后封闭；苗后2～4叶期用氰氟草酯等针对性药剂；抽穗后防效极差，只能人工拔除。","identification_key_text":"叶片纤细柔软、无叶耳叶舌；基部丛生呈「鸡爪状」、茎节可生根；花序分枝细长、小穗极小呈灰紫色如雾状，这是与稗草最直观的区别。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":7,"cell_range":"A7:I7","row_sha256":"ca7cf3118a88d258a5ace607d43d4b9684f1b07d63c483167dcc242bc78e0110","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=7;cells=A7:I7"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('7ad48c7f-15be-599d-8398-e49dfac83d9a'::uuid, '04489023-43ed-53ff-9763-e5878e30eefb'::uuid, 1, '浙江适用杂草：双穗雀稗', '{"kind":"weed","item_id":"zj-weed-r8","weed_name":"双穗雀稗","canonical_name":"双穗雀稗","scientific_name":"Paspalum distichum","family_genus":"禾本科·雀稗属","companion_crops":["水稻","甘蔗","蔬菜","果园","草坪"],"distribution_note":"","distribution_provinces":["广东","广西","福建","海南","云南","江苏","浙江","安徽","江西","湖北","湖南","四川","台湾"],"growth_stages_text":"① 幼苗期：匍匐茎贴地蔓延、节节生根；② 营养生长期：以地下根茎和匍匐茎无性繁殖为主，形成连片草毡，极难拔除；③ 抽穗期：总状花序通常2枚（故名双穗）呈「V」形顶生；④ 越冬期：根茎在土中越冬，次春萌发。","best_control_stage_text":"营养生长前期（匍匐茎尚未连片时），以草甘膦类灭生性药剂或土壤处理为主；一旦连片成毡，只能依赖多次施药加耕作。","spray_window_text":"水稻田在整地后、移栽前土壤处理；甘蔗与果园在杂草萌发初期喷施；冬季结合耕翻破坏根茎。","identification_key_text":"总状花序2枚呈「V」字形（偶有3枚），小穗扁圆、成两行排列；具粗壮匍匐茎和地下根茎，节上生根，整株难以拔出；常成片生长形成草毡。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":8,"cell_range":"A8:I8","row_sha256":"cc0cfec6e84ed41db781964882a7228455ba17ef352bc9fe905f8ebed811fed1","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=8;cells=A8:I8"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('617d3672-10ff-546d-a081-1929dfa48e8f'::uuid, '176063c4-efc4-5e23-99bc-e7752ef3925f'::uuid, 1, '浙江适用杂草：马唐', '{"kind":"weed","item_id":"zj-weed-r9","weed_name":"马唐","canonical_name":"马唐","scientific_name":"Digitaria sanguinalis","family_genus":"禾本科·马唐属","companion_crops":["玉米","大豆","花生","棉花","甘蔗","蔬菜","果园","草坪"],"distribution_note":"全国","distribution_provinces":["北京","天津","河北","山西","山东","河南","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","海南","四川","重庆","贵州","云南","陕西","甘肃","宁夏","新疆","辽宁","吉林","黑龙江","内蒙古","台湾"],"growth_stages_text":"① 幼苗期：第一片真叶短小、叶片带紫红色（重要识别特征）；② 分蘖期：基部倾卧地面、节上生根，分蘖多、形成丛生状；③ 拔节期：直立部分升高，株高30～60cm；④ 抽穗期：总状花序3～8枚呈指状排列（故称「马唐」）；⑤ 成熟期：种子随熟随落，繁殖力极强。","best_control_stage_text":"幼苗期至3～4叶期，未分蘖前。一旦基部节生根、形成匍匐分蘖，防效大幅下降。","spray_window_text":"旱田播后苗前封闭处理；苗后3～4叶期茎叶喷雾；果园、非耕地可在生长前期施用灭生性药剂。","identification_key_text":"幼苗第一片真叶带紫红色是田间最快识别特征；成株总状花序3～8枚呈指状辐射排列；茎基部节上生根、倾卧地面、易整株拔起；叶片较软、无叶耳。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":9,"cell_range":"A9:I9","row_sha256":"b39a2ef3bc50d53681361783e6580fbcf20413a4d0dd8db64ec82027b6aca54c","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=9;cells=A9:I9"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '["species_crabgrass"]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('08c26fe5-3edf-5d11-b96a-9f19cbffe92f'::uuid, '83e880c7-6b62-54e9-b914-5dbc256a402c'::uuid, 1, '浙江适用杂草：升马唐', '{"kind":"weed","item_id":"zj-weed-r10","weed_name":"升马唐","canonical_name":"升马唐","scientific_name":"Digitaria ciliaris","family_genus":"禾本科·马唐属","companion_crops":["玉米","大豆","棉花","花生","蔬菜","果园"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","陕西","辽宁","台湾"],"growth_stages_text":"① 幼苗期：叶片较短、边缘有毛；② 分蘖期：茎基部强烈匍匐、节上生根，蔓延快；③ 抽穗期：总状花序4～10枚，比马唐更多、更细长；④ 成熟期：种子细小、随熟落粒。","best_control_stage_text":"3～4叶期前。升马唐生长速度比马唐更快，必须在幼苗期抓紧。","spray_window_text":"播后苗前封闭；苗后早期茎叶处理，与马唐同期但需略提早。","identification_key_text":"叶鞘和叶片边缘密生疣基毛（手感粗糙）；总状花序数目比马唐多（4～10枚）、排列更松散；基部匍匐性比马唐更强、蔓延更快。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":10,"cell_range":"A10:I10","row_sha256":"66e53f72397237c421b578bd144a3f63d4a4c8512d7ec39f62fc54b046e68f1c","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=10;cells=A10:I10"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('13fb9e9b-009b-5aee-96fa-a1593233ff08'::uuid, '7910fd45-e8a8-5774-ae8e-aed9c1d59a2a'::uuid, 1, '浙江适用杂草：狗尾草', '{"kind":"weed","item_id":"zj-weed-r11","weed_name":"狗尾草","canonical_name":"狗尾草","scientific_name":"Setaria viridis","family_genus":"禾本科·狗尾草属","companion_crops":["玉米","大豆","谷子","高粱","花生","棉花","蔬菜","果园"],"distribution_note":"全国各省份均有分布","distribution_provinces":["北京","天津","河北","山西","内蒙古","辽宁","吉林","黑龙江","山东","河南","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","重庆","贵州","云南","陕西","甘肃","宁夏","青海","新疆","台湾"],"growth_stages_text":"① 幼苗期：叶片狭长、浅绿，茎基部带紫红色；② 分蘖期：分蘖少、多直立；③ 抽穗期：圆锥花序紧缩呈圆柱状、密生刚毛，形似狗尾，株高30～100cm；④ 成熟期：种子椭圆形，随熟落粒，单株可结籽数千粒。","best_control_stage_text":"2～4叶期幼苗阶段。狗尾草抽穗后茎秆坚硬、根系发达，防除成本成倍增加。","spray_window_text":"播后苗前土壤封闭；苗后2～4叶期茎叶处理；谷子田须选用对谷子安全的专用药剂。","identification_key_text":"圆锥花序紧缩成圆柱形、密被刚毛、形如狗尾，是其最典型特征；叶片狭长、叶鞘边缘有毛；幼苗茎基部紫红色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":11,"cell_range":"A11:I11","row_sha256":"43c81c62dd5fe2ad6fcd113f551226c9a177da95fbc7ffeb25bc9edada3fe10b","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=11;cells=A11:I11"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '["species_foxtail"]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('c792eee2-b795-5b07-bff6-6bc42f9fff76'::uuid, 'a5c8a339-96e8-584d-a4fd-fdfff7bd7f69'::uuid, 1, '浙江适用杂草：金色狗尾草', '{"kind":"weed","item_id":"zj-weed-r12","weed_name":"金色狗尾草","canonical_name":"金色狗尾草","scientific_name":"Setaria glauca","family_genus":"禾本科·狗尾草属","companion_crops":["玉米","大豆","谷子","高粱","花生","棉花","蔬菜"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","广东","广西","四川","云南","陕西","辽宁","台湾"],"growth_stages_text":"① 幼苗期：叶片较宽、略带灰绿；② 分蘖期：分蘖较狗尾草多，株型较粗壮；③ 抽穗期：圆锥花序较粗短、刚毛金黄色（故名），株高20～60cm；④ 成熟期：种子较大、黄褐色。","best_control_stage_text":"2～3叶期。金色狗尾草比狗尾草更耐旱耐贫瘠、分蘖更多，需比狗尾草更早防除。","spray_window_text":"播后苗前封闭；苗后2～3叶期处理；果园与非耕地可用灭生性药剂。","identification_key_text":"花序刚毛呈金黄色、明显短粗；植株较矮壮、常从基部分枝；叶片宽而略厚、灰绿色，与狗尾草的鲜绿色狭叶有区别。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":12,"cell_range":"A12:I12","row_sha256":"693173466f005937349f463ef968fd52e9caaa0f580ab90939ef72ff0ccd1879","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=12;cells=A12:I12"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('5639c392-7d75-5d24-be73-9c20f2b9f1fa'::uuid, 'eac70ab9-aac0-5d50-aeb8-5b6f8c1e8f71'::uuid, 1, '浙江适用杂草：牛筋草', '{"kind":"weed","item_id":"zj-weed-r14","weed_name":"牛筋草","canonical_name":"牛筋草","scientific_name":"Eleusine indica","family_genus":"禾本科·穇属","companion_crops":["玉米","大豆","棉花","花生","甘蔗","蔬菜","果园","草坪"],"distribution_note":"全国","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","海南","四川","重庆","贵州","云南","陕西","甘肃","辽宁","台湾"],"growth_stages_text":"① 幼苗期：叶片扁平、淡绿；② 分蘖期：基部极强韧、呈放射状平铺地面、节上生根，形成「盘状」株型；③ 抽穗期：穗状花序2～7枚呈指状排列于茎顶，株高15～90cm；④ 成熟期：种子黑褐色、随熟落粒。","best_control_stage_text":"3～4叶期。牛筋草一旦基部木质化、根系深扎，徒手无法拔出，必须在小苗期解决。","spray_window_text":"播后苗前封闭处理；苗后3～4叶期茎叶喷雾；果园需在营养生长前期施药，成株须用灭生性药剂并加助剂。","identification_key_text":"基部极韧、茎扁、呈放射状平铺地面（形如「牛筋」故得名），成株几乎无法徒手拔除；穗状花序呈指状排列；须根发达、根颈处有白色硬结。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":14,"cell_range":"A14:I14","row_sha256":"36acbd99881004094d476191eda8a29c828c078881b10776eda60b454dbda91d","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=14;cells=A14:I14"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '["species_goosegrass"]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('934a0174-f331-5783-bd70-fe26e2792b4d'::uuid, '03d33504-eb95-5b34-a838-3b0fb84202f4'::uuid, 1, '浙江适用杂草：画眉草', '{"kind":"weed","item_id":"zj-weed-r16","weed_name":"画眉草","canonical_name":"画眉草","scientific_name":"Eragrostis pilosa","family_genus":"禾本科·画眉草属","companion_crops":["玉米","大豆","花生","棉花","蔬菜","果园"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","陕西","辽宁","新疆","台湾"],"growth_stages_text":"① 幼苗期：叶片细软、浅绿；② 分蘖期：丛生、株型纤细；③ 抽穗期：圆锥花序疏松开展、分枝细软，小穗细小，株高20～60cm；④ 成熟期：种子极小、量多。","best_control_stage_text":"2～4叶期。画眉草虽个体小但群体密度极高，需在幼苗期压低基数。","spray_window_text":"播后苗前封闭；苗后早期茎叶处理。","identification_key_text":"圆锥花序疏松开展如网状、小穗细小；植株纤细柔软、叶片窄薄，与马唐、狗尾草的粗壮株型不同。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":16,"cell_range":"A16:I16","row_sha256":"655b68b6beec9acb54beb670d5089e4ec821c84062f25b01ff98b2c8f77ffbbc","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=16;cells=A16:I16"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('a4a75e92-ac25-54f0-a062-613c813c56de'::uuid, 'd5ab44c5-5305-580e-96d7-90b253f030d3'::uuid, 1, '浙江适用杂草：看麦娘', '{"kind":"weed","item_id":"zj-weed-r19","weed_name":"看麦娘","canonical_name":"看麦娘","scientific_name":"Alopecurus aequalis","family_genus":"禾本科·看麦娘属","companion_crops":["小麦","大麦","油菜","绿肥","蔬菜"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","河南","山东","陕西","四川","重庆","贵州","云南","福建","广西"],"growth_stages_text":"① 幼苗期：叶片细软、鲜绿；② 分蘖期：基部丛生、分蘖多，株高10～30cm；③ 抽穗期：圆锥花序紧缩成圆柱形、灰绿色、质地柔软（形似麦穗但更细软），株高15～50cm；④ 成熟期：种子随熟落粒，随水流传播。","best_control_stage_text":"2～3叶期至分蘖初期（小麦播后30～45天、越冬前）。看麦娘抽穗早（3月即可抽穗），必须在抽穗前完成防除。","spray_window_text":"小麦播后苗前封闭；或小麦2～4叶期至越冬前茎叶处理；长江流域重点在冬前施药。","identification_key_text":"圆锥花序紧缩呈圆柱状、柔软下垂如「毛笔头」；植株细软、基部丛生；与日本看麦娘的区别在于看麦娘小穗较小、芒较短（约与小穗等长）、花药淡黄色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":19,"cell_range":"A19:I19","row_sha256":"acf42315aa9f41917477126018b8700f9024bff7fc8b62d15f019840423a2b43","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=19;cells=A19:I19"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '["species_shortawn_foxtail"]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('3540d193-f5f3-5291-9518-8bf1e09d687b'::uuid, 'e916c65c-5a0a-568c-8c8d-292d17f1b515'::uuid, 1, '浙江适用杂草：日本看麦娘', '{"kind":"weed","item_id":"zj-weed-r20","weed_name":"日本看麦娘","canonical_name":"日本看麦娘","scientific_name":"Alopecurus japonicus","family_genus":"禾本科·看麦娘属","companion_crops":["小麦","大麦","油菜"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","河南","山东","上海","四川","贵州","云南","陕西"],"growth_stages_text":"① 幼苗期：与看麦娘相似但植株较粗壮；② 分蘖期：分蘖多、株型较直立；③ 抽穗期：圆锥花序较粗大、芒明显长于小穗并外露，花药橙黄色或褐色，株高30～70cm；④ 成熟期：种子落粒性强。","best_control_stage_text":"2～4叶期至越冬前。日本看麦娘抗药性（尤其对精噁唑禾草灵、炔草酯）在许多麦区已很突出，必须早防并轮换药剂。","spray_window_text":"小麦播后苗前封闭；冬前（2～5叶期）茎叶处理，注意药剂轮换以延缓抗性。","identification_key_text":"与看麦娘关键区别：芒明显长于小穗并伸出颖外、花药橙黄色至褐色（看麦娘花药淡黄）；圆锥花序较粗大；植株更粗壮、抗药性更强。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":20,"cell_range":"A20:I20","row_sha256":"d1a73315973bf60b45bf038c501de6dd5feef7daa1986c732b59cab3990aa12b","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=20;cells=A20:I20"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('449ce3e4-e400-59c9-bc8f-871aba572bee'::uuid, 'ac2d9519-3291-5b20-964f-5e891773d279'::uuid, 1, '浙江适用杂草：棒头草', '{"kind":"weed","item_id":"zj-weed-r21","weed_name":"棒头草","canonical_name":"棒头草","scientific_name":"Polypogon fugax","family_genus":"禾本科·棒头草属","companion_crops":["小麦","大麦","油菜","蔬菜"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","河南","山东","四川","重庆","贵州","云南","陕西","福建"],"growth_stages_text":"① 幼苗期：叶片细软；② 分蘖期：基部丛生、株型纤细；③ 抽穗期：圆锥花序紧缩呈棒状或卵形、芒细短，株高15～60cm；④ 成熟期：种子细小、量多。","best_control_stage_text":"2～4叶期。","spray_window_text":"小麦播后苗前封闭；冬前茎叶处理。","identification_key_text":"圆锥花序紧缩成棒状或卵形、密被细芒；植株较看麦娘更高、叶鞘常带紫色；穗形似「棒头」而得名。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":21,"cell_range":"A21:I21","row_sha256":"618bf58340b8c2874bdeb4d49791efa2c7d3cc9175899430b29c23f3d16790c7","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=21;cells=A21:I21"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('a3320c3e-23a6-5b13-9d57-bec3e50e7303'::uuid, '00256af6-1291-5353-adee-1c096cca67ab'::uuid, 1, '浙江适用杂草：菵草', '{"kind":"weed","item_id":"zj-weed-r22","weed_name":"菵草","canonical_name":"菵草","scientific_name":"Beckmannia syzigachne","family_genus":"禾本科·菵草属","companion_crops":["小麦","油菜","水稻"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","河南南部","四川","云南","黑龙江","上海"],"growth_stages_text":"① 幼苗期：叶片细长、浅绿；② 分蘖期：丛生、株型较高；③ 抽穗期：圆锥花序分枝紧贴主轴、小穗扁圆呈「菵」状排列，株高30～90cm；④ 成熟期：种子随熟落粒。","best_control_stage_text":"2～4叶期至越冬前。菵草在长江流域稻茬麦田常成灾，且对多种麦田除草剂抗性强。","spray_window_text":"小麦播后苗前封闭；冬前茎叶处理，宜与封闭处理结合；注意药剂轮换。","identification_key_text":"圆锥花序分枝短、紧贴主轴、小穗扁圆形呈两行排列；植株较高、叶片较宽，常在稻茬麦田形成高密度群落。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":22,"cell_range":"A22:I22","row_sha256":"dec2be70cefc85bfbda0a55848aa88ccfb0b42c846a0d58ffe0bfe70e1cc57cc","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=22;cells=A22:I22"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed","crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('2ffe0745-330c-52f8-beed-bdd0779b1df3'::uuid, '334c85c9-bc91-59db-a005-c9154eaa9712'::uuid, 1, '浙江适用杂草：硬草', '{"kind":"weed","item_id":"zj-weed-r23","weed_name":"硬草","canonical_name":"硬草","scientific_name":"Sclerochloa kengiana","family_genus":"禾本科·硬草属","companion_crops":["小麦","大麦","油菜"],"distribution_note":"","distribution_provinces":["江苏","安徽","河南","山东","湖北","上海","浙江"],"growth_stages_text":"① 幼苗期：叶片细硬、深绿；② 分蘖期：丛生、基部坚硬；③ 抽穗期：圆锥花序较紧密、小穗排列成两行，株高20～60cm；④ 成熟期：种子随熟落粒。","best_control_stage_text":"2～4叶期至越冬前。硬草茎秆坚硬、抽穗早，须在拔节前处理。","spray_window_text":"小麦播后苗前封闭；冬前茎叶处理，选用对硬草有效的药剂。","identification_key_text":"植株基部坚硬、呈丛生状（「硬草」得名）；叶片狭细、深绿、质地硬；穗形较看麦娘小且紧实。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":23,"cell_range":"A23:I23","row_sha256":"9413d94a9ba2d13843c7a25435ec2456ac044e77009a8a9fdef9060a79609399","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=23;cells=A23:I23"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('9bd0824a-a584-5038-a4aa-22b3df07730c'::uuid, '915bc8c5-0e5d-5e17-bac3-8f7af5a7d8b6'::uuid, 1, '浙江适用杂草：雀稗', '{"kind":"weed","item_id":"zj-weed-r26","weed_name":"雀稗","canonical_name":"雀稗","scientific_name":"Paspalum thunbergii","family_genus":"禾本科·雀稗属","companion_crops":["水稻","大豆","甘蔗","蔬菜","果园"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","云南","台湾"],"growth_stages_text":"① 幼苗期：叶片较宽、有毛；② 分蘖期：丛生、基部较粗；③ 抽穗期：总状花序3～5枚、小穗成两行排列、边缘有毛；④ 成熟期：种子随熟落粒。","best_control_stage_text":"3～5叶期。","spray_window_text":"旱田封闭或苗后早期处理；稻田结合整地处理。","identification_key_text":"总状花序3～5枚；小穗成两行排列、边缘具白色长毛（与双穗雀稗的双穗区别明显）；叶片较宽、两面有毛。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":26,"cell_range":"A26:I26","row_sha256":"58b22d9bc811c8fb287f6ac8eba82e48f3a5c3fe1cf2aadce9f83776ab767fb6","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=26;cells=A26:I26"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('7348d240-45bc-53d5-8a1d-2e70ec03febd'::uuid, 'c9f41520-f964-5f88-90d4-544d1be00215'::uuid, 1, '浙江适用杂草：荩草', '{"kind":"weed","item_id":"zj-weed-r27","weed_name":"荩草","canonical_name":"荩草","scientific_name":"Arthraxon hispidus","family_genus":"禾本科·荩草属","companion_crops":["玉米","大豆","果树","茶园","非耕地"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","陕西","辽宁","台湾"],"growth_stages_text":"① 幼苗期：茎细弱、基部匍匐；② 营养生长期：匍匐茎蔓延、节上生根；③ 抽穗期：总状花序数枚呈指状排列、小穗有芒，株高30～60cm；④ 成熟期：种子随熟落粒。","best_control_stage_text":"营养生长前期。荩草以匍匐茎无性繁殖为主，须在蔓延前处理。","spray_window_text":"果园、茶园与非耕地生长前期喷施灭生性药剂；农田结合播后封闭。","identification_key_text":"茎细弱、基部匍匐并节上生根；总状花序呈指状排列、小穗具芒；叶片基部抱茎、叶基常带紫色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":27,"cell_range":"A27:I27","row_sha256":"aef4491621fc5489af272673d661c9bf89605006f6e5ed59896168b58bf418ab","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=27;cells=A27:I27"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('f66b1d81-3a16-50c0-99c9-ebca94292f1b'::uuid, '47cd44b6-61b7-58e1-9c28-de26401340a0'::uuid, 1, '浙江适用杂草：白茅（茅草）', '{"kind":"weed","item_id":"zj-weed-r28","weed_name":"白茅（茅草）","canonical_name":"白茅","scientific_name":"Imperata cylindrica","family_genus":"禾本科·白茅属","companion_crops":["果园","茶园","甘蔗","橡胶园","非耕地","旱作农田"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","海南","四川","重庆","贵州","云南","陕西","辽宁","台湾"],"growth_stages_text":"① 地下根茎期（主要繁殖阶段）：地下根茎发达、白色有节、蔓延极广，断节即可萌发新株；② 幼苗期：由根茎萌发的芽鞘尖锐、可穿透硬土；③ 抽穗期：圆锥花序紧缩成圆柱状、密生白色丝状柔毛（故名白茅），株高30～90cm；④ 结实期：种子带毛、随风传播。","best_control_stage_text":"根茎萌发初期至幼苗期（株高10～20cm），且必须配合多次耕翻清除根茎。白茅一旦形成连片根茎网络，单次施药几乎无效。","spray_window_text":"果园、茶园在春季根茎萌发期用灭生性药剂（草甘膦加助剂）连续2～3次；农田结合深翻拾除根茎；甘蔗田在萌发前土壤处理。","identification_key_text":"地下白色有节根茎粗壮、味甜、断节可萌发；圆锥花序紧缩成圆柱状、密被白色丝状长柔毛，远看如白色毛刷；叶片狭长、边缘粗糙、中脉明显偏白。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":28,"cell_range":"A28:I28","row_sha256":"9770c15d8b3601dff9d7476d97f1e910e57b16b5331634ac20c5aee914ae6544","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=28;cells=A28:I28"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('72a22e57-7436-582d-8baa-00b44e9cbd35'::uuid, '48e19eb8-33c3-574b-b2ee-d7e57fbffd36'::uuid, 1, '浙江适用杂草：狗牙根（爬根草）', '{"kind":"weed","item_id":"zj-weed-r29","weed_name":"狗牙根（爬根草）","canonical_name":"狗牙根","scientific_name":"Cynodon dactylon","family_genus":"禾本科·狗牙根属","companion_crops":["果园","茶园","甘蔗","棉花","草坪","非耕地"],"distribution_note":"","distribution_provinces":["河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","海南","四川","重庆","贵州","云南","陕西","甘肃","台湾"],"growth_stages_text":"① 匍匐茎期：地上匍匐茎贴地蔓延、节节生根，地下根茎可深入土层1m；② 幼苗/返青期：春季由根茎和匍匐茎快速萌发；③ 抽穗期：穗状花序3～6枚呈指状排列、紫红色，株高10～40cm；④ 越冬期：以根茎和匍匐茎在土中越冬。","best_control_stage_text":"匍匐茎蔓延初期（春季返青后株高10cm以内），并配合多次耕翻。根茎一旦深扎，机械与化学防除都极困难。","spray_window_text":"果园、茶园、甘蔗田在返青初期施灭生性药剂，间隔30～45天重复1次；农田结合深翻、覆膜。","identification_key_text":"具地上匍匐茎与地下根茎双重繁殖器官、节上生根；穗状花序3～6枚呈指状排列、紫红色；叶片短而硬、常带灰绿；耐践踏、修剪后恢复快。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":29,"cell_range":"A29:I29","row_sha256":"5df12186237c8d1e3d62a9a0b08ae8c584c0b43f37567e311b56f1c5b1143857","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=29;cells=A29:I29"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('29d98f12-f5db-5fb2-95c5-54a4e6bf3fda'::uuid, '13ee2357-9eb9-574b-be64-eecdbf7df38e'::uuid, 1, '浙江适用杂草：芦苇', '{"kind":"weed","item_id":"zj-weed-r30","weed_name":"芦苇","canonical_name":"芦苇","scientific_name":"Phragmites australis","family_genus":"禾本科·芦苇属","companion_crops":["稻田","湿地农田","果园","非耕地","沟渠边"],"distribution_note":"","distribution_provinces":["黑龙江","吉林","辽宁","内蒙古","河北","天津","山东","江苏","安徽","江西","湖北","湖南","浙江","上海","福建","广东","广西","四川","云南","青海","新疆"],"growth_stages_text":"① 根状茎期：地下根状茎粗壮、横走、蔓延极广（是主要繁殖方式）；② 幼苗期：春季芽鞘出土、植株直立快速生长；③ 抽穗期：圆锥花序大型、密生柔毛下垂，株高可达1.5～4m；④ 越冬期：地上部枯死、根状茎越冬。","best_control_stage_text":"幼苗期至株高30cm前（根状茎储备营养耗尽前）。株高超过1m后根系与茎秆木质化，防效极差。","spray_window_text":"稻田整地前用灭生性药剂处理；果园与非耕地选择生长前期，需高浓度加助剂，间隔30天重复；长期治理配合深翻与水旱轮作。","identification_key_text":"植株高大直立、茎秆坚硬中空；叶片长披针形、边缘粗糙；圆锥花序大型、密生白色柔毛下垂；地下根状茎粗壮白色、横走蔓延。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":30,"cell_range":"A30:I30","row_sha256":"0343f13e52d946dcf183aac41c026f165de1fa41fc569355a4ad4b37c9e4ab4a","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=30;cells=A30:I30"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('b0e6dfa6-ba36-53eb-bfc4-b2aefe69a504'::uuid, '60502dab-867d-5802-89b3-41336ab7eebf'::uuid, 1, '浙江适用杂草：鹅观草', '{"kind":"weed","item_id":"zj-weed-r31","weed_name":"鹅观草","canonical_name":"鹅观草","scientific_name":"Roegneria kamoji","family_genus":"禾本科·鹅观草属","companion_crops":["小麦","油菜","果园","非耕地"],"distribution_note":"","distribution_provinces":["江苏","安徽","湖北","湖南","江西","浙江","河南","山东","陕西","四川","云南","贵州","甘肃"],"growth_stages_text":"① 幼苗期：叶片较软、绿色；② 分蘖期：丛生、分蘖力强；③ 抽穗期：穗状花序细长下垂、小穗具长芒，株高30～100cm；④ 成熟期：种子随熟落粒。","best_control_stage_text":"2～5叶期。鹅观草常在田边、地头先发生并向田内扩展。","spray_window_text":"田边与田内同步处理；苗后早期茎叶喷雾。","identification_key_text":"穗状花序细长、常弯曲下垂、小穗具长芒；植株丛生、叶片柔软，与雀麦的开展圆锥花序区别明显。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":31,"cell_range":"A31:I31","row_sha256":"5944d636a84b3e8f8bb8fc6b678a7aea9dab328711de2a79e5b4c6f656f13293","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=31;cells=A31:I31"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('ea7358d7-7b05-586d-af3a-884abb8020b7'::uuid, '65bc09de-f080-5c93-806b-fbe1196921bd'::uuid, 1, '浙江适用杂草：茼草（日本茼草）', '{"kind":"weed","item_id":"zj-weed-r32","weed_name":"茼草（日本茼草）","canonical_name":"茼草","scientific_name":"Beckmannia syzigachne（地方名，与菵草同种）","family_genus":"禾本科·菵草属","companion_crops":["小麦","油菜","水稻"],"distribution_note":"","distribution_provinces":["江苏","安徽","湖北","浙江","上海","河南"],"growth_stages_text":"① 幼苗期：水生型叶片细长柔软；② 分蘖期：丛生、耐水湿；③ 抽穗期：圆锥花序细长、小穗扁圆；④ 成熟期：种子随水传播。","best_control_stage_text":"2～4叶期。为菵草在长江下游的地方俗称，防除同菵草。","spray_window_text":"稻茬麦田冬前处理；与菵草一并防治，勿重复计数。","identification_key_text":"常生于稻茬麦田与沟渠边、喜湿；圆锥花序较菵草的棒状穗更显细长、小穗扁圆；植株较柔软。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":32,"cell_range":"A32:I32","row_sha256":"36b5f86ff6b5d08f9fa9c38661b5f9d4852c5082d73df47278da209a36a5cdc1","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=32;cells=A32:I32"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed","crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('d83e00b8-968b-513e-84f1-4a3a4bdeda5f'::uuid, '0c05c7c6-d832-5514-bcf4-f72fb2a3a861'::uuid, 1, '浙江适用杂草：虮子草', '{"kind":"weed","item_id":"zj-weed-r37","weed_name":"虮子草","canonical_name":"虮子草","scientific_name":"Leptochloa panicea","family_genus":"禾本科·千金子属","companion_crops":["水稻","棉花","大豆","蔬菜","甘蔗"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","广东","广西","福建","四川","云南","台湾"],"growth_stages_text":"① 幼苗期：叶片纤细；② 分蘖期：丛生、株型细弱；③ 抽穗期：圆锥花序疏散、小穗极小呈紫色；④ 成熟期：种子极小。","best_control_stage_text":"2～4叶期。","spray_window_text":"稻田与旱田早期处理，参照千金子。","identification_key_text":"与千金子极相似但植株更细弱、小穗更小；花序分枝更细软、呈疏散的紫色雾状。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":37,"cell_range":"A37:I37","row_sha256":"7872f72d3e74b17c7236823cd32d5e37aa681efd71905575530e83dd33888a31","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=37;cells=A37:I37"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('1986b5e9-3b80-5e73-a548-f110453331e9'::uuid, 'f3234c8f-d177-5b22-83ec-2df0353e2b9c'::uuid, 1, '浙江适用杂草：求米草', '{"kind":"weed","item_id":"zj-weed-r38","weed_name":"求米草","canonical_name":"求米草","scientific_name":"Oplismenus undulatifolius","family_genus":"禾本科·求米草属","companion_crops":["大豆","玉米","果园","茶园","林地"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","贵州","云南","陕西","河南"],"growth_stages_text":"① 幼苗期：茎细弱蔓生；② 营养生长期：匍匐茎蔓延、节上生根，喜阴湿；③ 抽穗期：圆锥花序稀疏、小穗具长芒；④ 成熟期：种子带芒易粘附。","best_control_stage_text":"营养生长前期。求米草多在荫蔽果园、茶园成灾，需在蔓延前处理。","spray_window_text":"果园、茶园生长前期施药；结合清除田间遮阴物、改善通风。","identification_key_text":"茎细弱蔓生、节上生根；叶片卵状披针形、有横向波纹（「undulatifolius」即波状叶）；小穗具黏性长芒，易粘附衣物。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":38,"cell_range":"A38:I38","row_sha256":"1c553598e3dd8130a2c492f6b6a4fe534da9a2f0e7fa043386f650be9667243c","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=38;cells=A38:I38"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_soybean","crop_corn"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('24a352d3-c896-5db1-baea-6d0301bbf83a'::uuid, '29ba81f2-d4cf-578a-8b01-52f81fa2a7ed'::uuid, 1, '浙江适用杂草：李氏禾（游草）', '{"kind":"weed","item_id":"zj-weed-r41","weed_name":"李氏禾（游草）","canonical_name":"李氏禾","scientific_name":"Leersia hexandra","family_genus":"禾本科·李氏禾属","companion_crops":["水稻","湿地农田","沟渠边"],"distribution_note":"","distribution_provinces":["广东","广西","福建","海南","云南","江西","湖南","湖北","浙江","四川","台湾"],"growth_stages_text":"① 匍匐茎期：匍匐茎在水面或湿地蔓延、节上生根；② 幼苗期：由匍匐茎萌发；③ 抽穗期：圆锥花序开展、小穗无芒；④ 越冬期：匍匐茎越冬。","best_control_stage_text":"匍匐茎蔓延初期。李氏禾以无性繁殖为主，须在连片前处理。","spray_window_text":"稻田整地前处理；沟渠边结合清淤。","identification_key_text":"具匍匐茎、节上生根；叶片与水稻极相似但更粗糙、边缘有锯齿感；小穗无芒。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":41,"cell_range":"A41:I41","row_sha256":"25752e672a16822fab0cc69477bb16c2f10904138cf02a3ac12f80352e03879a","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=41;cells=A41:I41"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('bda36c7b-1b1f-5797-b854-4c1b8e3d5c21'::uuid, 'fedafad2-9c87-5dfc-a796-da86ebd6ca9a'::uuid, 1, '浙江适用杂草：狗尾草（莠狗尾草／巨大狗尾草）', '{"kind":"weed","item_id":"zj-weed-r45","weed_name":"狗尾草（莠狗尾草／巨大狗尾草）","canonical_name":"狗尾草","scientific_name":"Setaria viridis var. major","family_genus":"禾本科·狗尾草属","companion_crops":["玉米","大豆","谷子","高粱","棉花"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","陕西","辽宁","吉林","黑龙江","四川","云南"],"growth_stages_text":"① 幼苗期：叶片宽大、深绿；② 分蘖期：株型高大；③ 抽穗期：圆锥花序大型、刚毛长；④ 成熟期：种子量大。","best_control_stage_text":"3～4叶期。","spray_window_text":"播后苗前封闭；苗后早期处理。","identification_key_text":"植株显著高大粗壮（可达1.5m）、叶片宽大深绿；花序长大；与谷子苗期相似，谷子田需谨慎选药。","zhejiang_evidence_strength":"name_only","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":45,"cell_range":"A45:I45","row_sha256":"87f983ccd2412a4369eb1865d85c04950bed28e8f52621db6871639fe29bd028","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=45;cells=A45:I45"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '["species_foxtail"]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('317358c0-8309-5906-a813-6f9fccd0e9f7'::uuid, 'a01346a8-49f2-55e5-b579-788fe70364ca'::uuid, 1, '浙江适用杂草：香附子（莎草）', '{"kind":"weed","item_id":"zj-weed-r46","weed_name":"香附子（莎草）","canonical_name":"香附子","scientific_name":"Cyperus rotundus","family_genus":"莎草科·莎草属","companion_crops":["棉花","玉米","大豆","花生","甘蔗","蔬菜","果园","水稻田边"],"distribution_note":"","distribution_provinces":["山东","河南","河北","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","海南","四川","重庆","云南","陕西","新疆","台湾"],"growth_stages_text":"① 块茎期（主要繁殖阶段）：地下形成串珠状块茎（「香附子」），可深入土层30cm，休眠与萌发交错进行；② 幼苗期：由块茎萌发，叶片三角状排列、深绿有光泽；③ 开花期：聚伞花序复出、小穗扁平成两行、红褐色，株高15～60cm；④ 块茎越冬期：地上部枯死，块茎在土中越冬并逐年累积。","best_control_stage_text":"块茎萌发初期至幼苗期（株高10cm以内），且必须连续多次防治并配合深翻。香附子是全球公认最难防除的杂草之一，一次施药绝不可能根除。","spray_window_text":"棉田、旱作田在苗前土壤封闭加苗后早期处理；果园在萌发初期连续2～3次施药；结合秋季深翻、轮作水稻（水淹可显著抑制块茎）。","identification_key_text":"地下有串珠状连接的黑褐色块茎、断面白色有香气（故名香附子）；叶片深绿、有光泽、呈三角状三列排列；茎横切面为三角形（三棱状）；花序红褐色、小穗扁平。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":46,"cell_range":"A46:I46","row_sha256":"3160b6dc9368e5f7ae4ea2babdace89e8abf10ddea24325e832154a55fa5d746","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=46;cells=A46:I46"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('f6ad7f03-0caa-54ec-ac87-f773bf11e9b6'::uuid, '58404d42-10e7-5a6c-a7a4-047824483594'::uuid, 1, '浙江适用杂草：异型莎草', '{"kind":"weed","item_id":"zj-weed-r48","weed_name":"异型莎草","canonical_name":"异型莎草","scientific_name":"Cyperus difformis","family_genus":"莎草科·莎草属","companion_crops":["水稻","湿地农田","蔬菜"],"distribution_note":"全国各稻区","distribution_provinces":["黑龙江","吉林","辽宁","江苏","浙江","安徽","江西","湖北","湖南","广东","广西","福建","海南","四川","重庆","贵州","云南","河南","陕西","山东","台湾"],"growth_stages_text":"① 幼苗期：叶片细软、浅绿；② 分蘖期：丛生、株型矮小（10～30cm）；③ 开花期：聚伞花序球形、小穗极多而密集呈球状（故名「异型」）、黄褐色；④ 结实期：种子极小、数量巨大，随水流与灌水传播。","best_control_stage_text":"幼苗期（2～4叶，株高5～10cm）。异型莎草抽穗开花极早、种子量极大，必须在抽穗前防除。","spray_window_text":"稻田移栽后5～10天土壤封闭或苗后早期（株高10cm以内）茎叶处理；直播稻田播后封闭。","identification_key_text":"聚伞花序由多数小穗密集聚成球形、黄褐色如小绒球，是田间最容易识别的特征；植株矮小丛生、叶片细软；种子极小、量极大。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":48,"cell_range":"A48:I48","row_sha256":"21a3f9296842768f90c1af28c324b8362a770729507582d368191aa91d1c57d5","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=48;cells=A48:I48"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('dd012a27-7876-5d8f-be24-2b17a0db8332'::uuid, '86e47b81-fffa-503d-9bfe-5fe4d34e5f31'::uuid, 1, '浙江适用杂草：碎米莎草', '{"kind":"weed","item_id":"zj-weed-r49","weed_name":"碎米莎草","canonical_name":"碎米莎草","scientific_name":"Cyperus iria","family_genus":"莎草科·莎草属","companion_crops":["水稻","棉花","大豆","蔬菜","果园"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","云南","河南","陕西","山东","台湾"],"growth_stages_text":"① 幼苗期：叶片细软、浅绿；② 分蘖期：丛生、株高20～60cm；③ 开花期：聚伞花序复出、小穗扁平呈黄褐色、穗轴明显；④ 结实期：种子小、量多。","best_control_stage_text":"幼苗期至分蘖初期（株高10～15cm以内）。","spray_window_text":"稻田移栽后5～10天处理；旱田苗前封闭加苗后早期处理。","identification_key_text":"聚伞花序复出、分枝较长、小穗扁平呈两行排列于穗轴上、黄褐色；植株比异型莎草高、比香附子矮；小穗不如异型莎草那样聚成球状。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":49,"cell_range":"A49:I49","row_sha256":"22dc425a4b41ea2bd34e88a02c4cb6f198cea2fd12ae162b94b821dcb84f2f9d","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=49;cells=A49:I49"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('dd9b384f-ada3-5d67-b88b-b7a60367831f'::uuid, '4e4ea9a6-5100-5cc0-b76c-150062535007'::uuid, 1, '浙江适用杂草：牛毛毡', '{"kind":"weed","item_id":"zj-weed-r50","weed_name":"牛毛毡","canonical_name":"牛毛毡","scientific_name":"Eleocharis yokoscensis","family_genus":"莎草科·荸荠属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["黑龙江","吉林","辽宁","江苏","浙江","安徽","江西","湖北","湖南","广东","广西","四川","云南","河北","山东","台湾"],"growth_stages_text":"① 幼苗期：由根茎萌发、叶片退化为针状如牛毛；② 蔓延期：以根茎和匍匐茎快速蔓延、形成密集草毡（是本种主要危害方式）；③ 开花期：小穗单生于茎顶、褐色；④ 越冬期：根茎在土中越冬。","best_control_stage_text":"根茎萌发初期至蔓延前期（形成草毡之前）。牛毛毡一旦连片成毡，水稻分蘖与扎根受严重影响，防除极为困难。","spray_window_text":"稻田移栽前整地时土壤处理，或移栽后5～10天早期处理；结合秋耕破坏根茎。","identification_key_text":"植株矮小密集如毡、叶片退化成针状（形如牛毛，故名）；茎细如线、绿色；小穗单生于茎顶、褐色；根系与根茎在表土层交织成网。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":50,"cell_range":"A50:I50","row_sha256":"11988e3a3d7862cdc6ba480ca8fa399bd63bcd2b539cf53cbc49aed12042eb86","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=50;cells=A50:I50"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('73058303-2df3-527e-a496-748b42b23cb5'::uuid, '309d2085-f346-5fab-9436-d55aad64cfa9'::uuid, 1, '浙江适用杂草：萤蔺（灯心草）', '{"kind":"weed","item_id":"zj-weed-r51","weed_name":"萤蔺（灯心草）","canonical_name":"萤蔺","scientific_name":"Scirpus juncoides","family_genus":"莎草科·藨草属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["黑龙江","吉林","辽宁","江苏","浙江","安徽","江西","湖北","湖南","广东","广西","福建","四川","云南","台湾"],"growth_stages_text":"① 幼苗期：由种子和根茎萌发、茎圆柱形似灯心；② 生长期：茎直立丛生、株高30～80cm、无叶片；③ 开花期：小穗单生或2～3枚聚生于茎顶、褐色；④ 结实期：种子小而多。","best_control_stage_text":"幼苗期至分蘖初期（株高20cm以内）。萤蔺茎秆坚硬光滑，药剂附着力差，须在幼苗期并加用展着剂。","spray_window_text":"稻田移栽后5～15天土壤或茎叶处理；注意加助剂改善附着；结合秋耕。","identification_key_text":"茎圆柱形、直立、光滑无叶片（叶片退化为鞘）、形如灯心草；小穗顶生、褐色；茎横切面圆形（区别于扁秆藨草的三棱形）。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":51,"cell_range":"A51:I51","row_sha256":"08386755e8a9f75b6439bb3d2eaa4092d8cb7d96c2de82668dc57dc0116ce510","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=51;cells=A51:I51"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('17099de4-1dd6-5159-9b31-2c277b297917'::uuid, '42ddcd43-76d8-5c71-a021-814ad22afa8d'::uuid, 1, '浙江适用杂草：日照飘拂草', '{"kind":"weed","item_id":"zj-weed-r53","weed_name":"日照飘拂草","canonical_name":"日照飘拂草","scientific_name":"Fimbristylis miliacea","family_genus":"莎草科·飘拂草属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","云南","台湾"],"growth_stages_text":"① 幼苗期：叶片细软；② 分蘖期：丛生、株高20～60cm；③ 开花期：聚伞花序复出、小穗极小极多、呈灰褐色雾状；④ 结实期：种子极小、量极大。","best_control_stage_text":"幼苗期至分蘖初期（株高10～15cm以内）。飘拂草种子极小、繁殖系数极高，须在抽穗前压低基数。","spray_window_text":"稻田早期处理（移栽后5～10天）；结合封闭处理。","identification_key_text":"聚伞花序多次复出、小穗极小极多、呈灰褐色雾状（「飘拂」得名）；植株细弱丛生；与碎米莎草区别在于小穗更小更多、花序更松散。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":53,"cell_range":"A53:I53","row_sha256":"711dcb32a34390bddd63e0b5d674fc1bcc7d8836318dcd1ce812234fc0be1742","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=53;cells=A53:I53"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('cba40e3b-f52e-534b-981f-660e33902225'::uuid, '4b31bc33-62fe-5668-a7a7-98088fcf06f2'::uuid, 1, '浙江适用杂草：水蜈蚣（短叶水蜈蚣）', '{"kind":"weed","item_id":"zj-weed-r54","weed_name":"水蜈蚣（短叶水蜈蚣）","canonical_name":"水蜈蚣","scientific_name":"Kyllinga brevifolia","family_genus":"莎草科·水蜈蚣属","companion_crops":["水稻田边","草坪","湿地","蔬菜"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","云南","台湾"],"growth_stages_text":"① 根茎期：具细长匍匐根茎、节上生根；② 幼苗期：丛生、株高5～30cm；③ 开花期：头状花序单生、绿色、下方有3枚叶状苞片呈放射状；④ 越冬期：根茎越冬。","best_control_stage_text":"根茎萌发初期至幼苗期。","spray_window_text":"草坪与田边在萌发初期处理；结合除草与改善排水。","identification_key_text":"头状花序单生茎顶、绿色、基部有3枚叶状苞片呈放射状展开（形似蜈蚣，故名）；具细长匍匐根茎、节上生根；植株矮小。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":54,"cell_range":"A54:I54","row_sha256":"9a28e7c5b2691171d3449f8182f9177feca047dbb1b46e4f69749559154329ca","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=54;cells=A54:I54"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('0e22e781-55b4-5e75-826e-ea75339af040'::uuid, '764c2d8e-3990-57e2-a89e-eac5af71a934'::uuid, 1, '浙江适用杂草：球穗扁莎', '{"kind":"weed","item_id":"zj-weed-r55","weed_name":"球穗扁莎","canonical_name":"球穗扁莎","scientific_name":"Pycreus globosus","family_genus":"莎草科·扁莎草属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","广东","广西","四川","云南","福建","台湾"],"growth_stages_text":"① 幼苗期：叶片细软；② 分蘖期：丛生；③ 开花期：聚伞花序、小穗扁平压扁、排列成球状穗；④ 结实期：种子小。","best_control_stage_text":"幼苗期至分蘖初期。","spray_window_text":"稻田早期处理，参照碎米莎草。","identification_key_text":"小穗明显扁平（压扁状）、呈球状排列于穗轴；植株较碎米莎草矮小、丛生。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":55,"cell_range":"A55:I55","row_sha256":"8a89bb715ad8333256be0eeb2e4516e9306ae31d01d789338232624caeb05216","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=55;cells=A55:I55"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('4e8c429f-0964-596f-a258-1b6fc8e3804d'::uuid, 'f9030768-896f-5c3a-a09f-24fbcd763e56'::uuid, 1, '浙江适用杂草：茳芏（席草）', '{"kind":"weed","item_id":"zj-weed-r57","weed_name":"茳芏（席草）","canonical_name":"茳芏","scientific_name":"Cyperus malaccensis","family_genus":"莎草科·莎草属","companion_crops":["水稻田边","湿地","沟渠边"],"distribution_note":"","distribution_provinces":["广东","广西","福建","海南","云南","江西","湖南","江苏","浙江","台湾"],"growth_stages_text":"① 根茎期：具粗壮匍匐根茎；② 幼苗期：茎三棱形、直立；③ 开花期：聚伞花序、小穗扁平；④ 越冬期：根茎越冬。","best_control_stage_text":"根茎萌发初期至幼苗期。","spray_window_text":"稻田边与沟渠边早期处理；结合清沟。","identification_key_text":"茎高而三棱形明显、粗壮、可编织席草；具粗壮匍匐根茎；喜水湿、常生于田边沟渠。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":57,"cell_range":"A57:I57","row_sha256":"95c2155f32cd6b0e516ea18dc8ca3eb8a7c269f10fb4160e2864af136bf0cb6d","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=57;cells=A57:I57"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('57710748-4bcf-5246-9f9a-504ca91f824e'::uuid, '3133d258-b96a-524e-8ba0-e734053ce5b3'::uuid, 1, '浙江适用杂草：刺子莞', '{"kind":"weed","item_id":"zj-weed-r58","weed_name":"刺子莞","canonical_name":"刺子莞","scientific_name":"Rhynchospora rubra","family_genus":"莎草科·刺子莞属","companion_crops":["水稻","湿地农田","草坪"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","福建","广东","广西","湖南","四川","云南","台湾"],"growth_stages_text":"① 幼苗期：叶片细硬；② 分蘖期：丛生；③ 开花期：头状花序下方具叶状苞片、小穗褐色、具刺状宿存花柱；④ 结实期：种子带刺状花柱基部。","best_control_stage_text":"幼苗期至分蘖初期。","spray_window_text":"草坪与稻田早期处理。","identification_key_text":"小穗的宿存花柱基部膨大成刺状（故名「刺子莞」）；头状花序下方有几枚叶状苞片；植株丛生、叶片细硬。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":58,"cell_range":"A58:I58","row_sha256":"df136c2b3c67dcd25560cd4dfeef069997ef7a5b7860a4bd9183306ddbd43f2b","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=58;cells=A58:I58"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('9a901564-3b18-5b24-8db0-03a488971b52'::uuid, '0d491198-77e6-5c45-abb7-52112d7fdb13'::uuid, 1, '浙江适用杂草：马齿苋', '{"kind":"weed","item_id":"zj-weed-r60","weed_name":"马齿苋","canonical_name":"马齿苋","scientific_name":"Portulaca oleracea","family_genus":"马齿苋科·马齿苋属","companion_crops":["蔬菜","玉米","大豆","花生","棉花","果园","瓜类"],"distribution_note":"全国各省份均有分布","distribution_provinces":["北京","天津","河北","山西","内蒙古","辽宁","吉林","黑龙江","上海","江苏","浙江","安徽","福建","江西","山东","河南","湖北","湖南","广东","广西","海南","重庆","四川","贵州","云南","西藏","陕西","甘肃","青海","宁夏","新疆","台湾"],"growth_stages_text":"① 幼苗期：肉质茎平卧、叶片肥厚倒卵形；② 营养生长期：茎匍匐或斜升、肉质多汁、节上生根，断枝即可成新株；③ 开花期：花小、黄色、簇生于枝顶，花期长（5～9月）；④ 结实期：蒴果盖裂、种子极小极多、黑色发亮，单株可结籽数万粒。","best_control_stage_text":"幼苗期至营养生长前期（株高/茎长10cm以内）。马齿苋肉质茎保水性强、断枝再生能力极强，一旦铺散连片，防除成本成倍增加。","spray_window_text":"蔬菜与旱作田播后苗前封闭（最有效）加苗后早期处理；果园与瓜田在幼苗期施药；结合中耕清除断枝（避免留于田间再生）。","identification_key_text":"茎肉质多汁、红褐色、平卧地面；叶片肥厚肉质、倒卵形、全缘、表面光滑；花小黄色；掐断茎有黏液、断枝落地即生根成活。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":60,"cell_range":"A60:I60","row_sha256":"86cff6c9f09fbde8e76c6ac7d238bec81ecfaeadcb618b751b7d65ae125f6a14","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=60;cells=A60:I60"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('7bb8edd1-cbb9-505f-9c4c-6f3bcb327a65'::uuid, '90c54214-d742-5408-9cbf-9ceb02b4a5ef'::uuid, 1, '浙江适用杂草：反枝苋', '{"kind":"weed","item_id":"zj-weed-r61","weed_name":"反枝苋","canonical_name":"反枝苋","scientific_name":"Amaranthus retroflexus","family_genus":"苋科·苋属","companion_crops":["玉米","大豆","花生","棉花","蔬菜","果园","向日葵"],"distribution_note":"全国各省份均有分布","distribution_provinces":["北京","天津","河北","山西","内蒙古","辽宁","吉林","黑龙江","上海","江苏","浙江","安徽","福建","江西","山东","河南","湖北","湖南","广东","广西","重庆","四川","贵州","云南","陕西","甘肃","宁夏","新疆","台湾"],"growth_stages_text":"① 幼苗期：下胚轴紫红色、子叶椭圆形；② 苗期：叶片菱状卵形、全缘、有长柄，茎及叶柄带红色；③ 旺长期：株高可达0.5～2m、茎粗壮直立、多分枝；④ 开花期：穗状圆锥花序顶生及腋生、密集成团、绿色；⑤ 结实期：种子极小、黑色发亮、数量极大（单株可达数十万粒）。","best_control_stage_text":"2～4叶期幼苗阶段。反枝苋生长极快、种子量极大，一旦株高超过20cm且根系扎深，防效显著下降并已开始竞争产量。","spray_window_text":"旱作田播后苗前土壤封闭（首选，苋属对封闭药剂敏感）加苗后2～4叶期茎叶处理；果园在幼苗期施药。","identification_key_text":"茎和叶柄常带红色；叶片菱状卵形、全缘无锯齿、顶端微凹有短尖；花序为密集成团的绿色穗状圆锥花序；幼苗期下胚轴紫红是田间识别捷径。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":61,"cell_range":"A61:I61","row_sha256":"21e8d26326d334f852ce9793757b2852eb80a2e210cb878bd66f2b72f9e4a8ef","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=61;cells=A61:I61"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('9f6b9d31-ec85-5ea1-9eb4-0001a5bd7e4b'::uuid, '795e0d4b-eec8-5771-8f4f-c5dc9700854c'::uuid, 1, '浙江适用杂草：凹头苋', '{"kind":"weed","item_id":"zj-weed-r62","weed_name":"凹头苋","canonical_name":"凹头苋","scientific_name":"Amaranthus lividus","family_genus":"苋科·苋属","companion_crops":["玉米","大豆","蔬菜","棉花","果园"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","陕西","辽宁","台湾"],"growth_stages_text":"① 幼苗期：茎绿色或带紫、叶片卵形；② 苗期：茎常基部分枝、平卧后上升；③ 旺长期：株高10～30cm（比反枝苋矮小）、茎细；④ 开花期：穗状花序细弱、绿色；⑤ 结实期：种子极小、黑色。","best_control_stage_text":"2～4叶期。凹头苋常贴地生长、株型矮小，易被忽略而错过防治窗口，须在幼苗期一并处理。","spray_window_text":"旱作田播后苗前封闭加苗后早期处理；蔬菜田注意采收间隔。","identification_key_text":"叶片顶端明显凹缺（「凹头」得名），与反枝苋顶端微凹不同；植株矮小细弱、常基部分枝平卧；叶片全缘。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":62,"cell_range":"A62:I62","row_sha256":"9c5e07877d7a05c8af2754c3ee0b866cfa71ca32eb93ab5ff8184ce300f5bb88","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=62;cells=A62:I62"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('46f9d8e6-5565-5962-8605-7c27d1e4efbd'::uuid, 'f221de4a-4180-5a64-a3bd-e564d5024d16'::uuid, 1, '浙江适用杂草：皱果苋', '{"kind":"weed","item_id":"zj-weed-r63","weed_name":"皱果苋","canonical_name":"皱果苋","scientific_name":"Amaranthus viridis","family_genus":"苋科·苋属","companion_crops":["玉米","大豆","蔬菜","棉花","果园"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","陕西","台湾"],"growth_stages_text":"① 幼苗期：茎绿色、叶片卵形；② 苗期：茎直立、多分枝；③ 旺长期：株高40～80cm；④ 开花期：穗状花序细长、绿色；⑤ 结实期：种子黑色、果皮皱缩（「皱果」得名）。","best_control_stage_text":"2～4叶期。","spray_window_text":"旱作田播后苗前封闭加苗后早期处理。","identification_key_text":"果实表面皱缩（是与其他苋属区分的关键，需在结实期观察）；叶片卵形、全缘；植株直立多分枝、全株绿色无红色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":63,"cell_range":"A63:I63","row_sha256":"d186666a7fbbd544f17edc52e8d63a4d18a4defe80fe666d496dcb23e990e355","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=63;cells=A63:I63"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('346e014c-1338-5b0f-9904-6b1afded2eb8'::uuid, 'dcd9fee2-64b2-5b61-99cf-0c9f901a2b62'::uuid, 1, '浙江适用杂草：刺苋', '{"kind":"weed","item_id":"zj-weed-r64","weed_name":"刺苋","canonical_name":"刺苋","scientific_name":"Amaranthus spinosus","family_genus":"苋科·苋属","companion_crops":["蔬菜","玉米","大豆","果园","非耕地"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","重庆","云南","贵州","台湾"],"growth_stages_text":"① 幼苗期：茎带红色、叶片卵形；② 苗期：叶腋生出锐刺；③ 旺长期：株高30～100cm、茎粗壮、叶腋有2枚锐刺；④ 开花期：穗状花序顶生及腋生；⑤ 结实期：种子极小、黑色。","best_control_stage_text":"2～4叶期（刺尚未硬化时）。刺苋叶腋锐刺会刺伤作业人员并妨碍机械除草，必须在小苗期处理。","spray_window_text":"蔬菜与果园苗前封闭加苗后早期处理；作业时注意防护手套。","identification_key_text":"叶腋具2枚坚硬锐刺（最典型特征，也是识别捷径）；茎常带红色；叶片卵形或菱状卵形；植株粗壮。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":64,"cell_range":"A64:I64","row_sha256":"cf96e4fd97d1248f66637cb56bd6fd818b9a8a7abce8399e029a11be18436cf7","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=64;cells=A64:I64"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('ee3edd31-4840-50a9-8a8c-4c2772368f0b'::uuid, '54085959-cf84-5496-91fe-7f0d104f2f15'::uuid, 1, '浙江适用杂草：藜（灰菜）', '{"kind":"weed","item_id":"zj-weed-r65","weed_name":"藜（灰菜）","canonical_name":"藜","scientific_name":"Chenopodium album","family_genus":"苋科（原藜科）·藜属","companion_crops":["小麦","玉米","大豆","油菜","蔬菜","甜菜","向日葵","果园"],"distribution_note":"全国各省份均有分布","distribution_provinces":["北京","天津","河北","山西","内蒙古","辽宁","吉林","黑龙江","上海","江苏","浙江","安徽","福建","江西","山东","河南","湖北","湖南","广东","广西","重庆","四川","贵州","云南","西藏","陕西","甘肃","青海","宁夏","新疆","台湾"],"growth_stages_text":"① 幼苗期：子叶狭长、下胚轴常带紫红；② 苗期：叶片菱状卵形、边缘有不规则锯齿、叶面常有白粉；③ 旺长期：株高30～150cm、茎直立、多分枝；④ 开花期：花小、绿色、密集成团生于枝顶及叶腋；⑤ 结实期：种子扁圆、黑色有光泽、数量极大。","best_control_stage_text":"2～4叶期幼苗阶段。藜在4叶后进入快速生长、株高迅速超过作物，且对多种除草剂耐性上升；麦田须在越冬前或返青早期处理。","spray_window_text":"麦田播后苗前封闭或冬前茎叶处理；玉米、大豆田封闭加苗后早期处理；甜菜田选用对甜菜安全的专用药剂。","identification_key_text":"叶片表面常有白色粉状物（幼嫩部分尤明显）；叶缘有不规则波状锯齿、叶形变化大（下部叶菱状、上部叶披针形）；幼苗下胚轴紫红；茎有纵棱、常带红紫色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":65,"cell_range":"A65:I65","row_sha256":"41818981d978e8922c9b80a7655647b5506f587fd84183dc46998684640e4bae","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=65;cells=A65:I65"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean","crop_rapeseed"]'::jsonb, '["species_lambsquarters"]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('a04d05f9-4d54-504a-ac41-3a043345eae7'::uuid, '7dd6618f-a277-540f-b8e8-d82c202f6e0b'::uuid, 1, '浙江适用杂草：小藜', '{"kind":"weed","item_id":"zj-weed-r66","weed_name":"小藜","canonical_name":"小藜","scientific_name":"Chenopodium serotinum","family_genus":"苋科（原藜科）·藜属","companion_crops":["小麦","油菜","蔬菜","玉米","大豆"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","四川","云南","陕西","辽宁","台湾"],"growth_stages_text":"① 幼苗期：叶片狭长、浅绿；② 苗期：叶片长圆状披针形、边缘有波状齿；③ 旺长期：株高20～60cm（较藜矮小）；④ 开花期：花小绿色、密集成团；⑤ 结实期：种子扁圆、黑色。","best_control_stage_text":"2～4叶期。","spray_window_text":"麦田与油菜田冬前处理；蔬菜田苗前封闭。","identification_key_text":"叶片较藜狭长（长圆形至披针形）、白粉较少；植株较藜矮小细弱；叶缘波状齿较浅。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":66,"cell_range":"A66:I66","row_sha256":"d5f218b4024cb9bf6559e1e59981174da9d081108beb8ed4aa85db3048191f06","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=66;cells=A66:I66"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed","crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('ed7b0cbd-35ed-50fa-84e5-9a4f192e14d8'::uuid, 'e60a221a-a83a-514a-af7a-5ab25a2453f0'::uuid, 1, '浙江适用杂草：苋菜（野苋）', '{"kind":"weed","item_id":"zj-weed-r68","weed_name":"苋菜（野苋）","canonical_name":"苋菜","scientific_name":"Amaranthus tricolor 等野生型","family_genus":"苋科·苋属","companion_crops":["蔬菜","玉米","大豆","棉花"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","云南","河南","山东","台湾"],"growth_stages_text":"① 幼苗期：叶片卵形、带红或绿；② 苗期：茎直立、多分枝；③ 旺长期：株高30～100cm；④ 开花期：穗状花序腋生及顶生；⑤ 结实期：种子极小、黑色。","best_control_stage_text":"2～4叶期。野生苋与栽培苋同属，菜地中易混淆，须在幼苗期辨认并处理。","spray_window_text":"蔬菜田苗前封闭加苗后早期定向处理（注意避开栽培苋）。","identification_key_text":"与栽培苋同属、形态接近，野生型植株较细弱、分枝多、叶片较小、花序较松散；幼苗期下胚轴常带红色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":68,"cell_range":"A68:I68","row_sha256":"4ed3f4e29fa38c590c85ff2761778d6877858404258a6718517b223f4b36ee4d","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=68;cells=A68:I68"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('00b456fe-c5ba-518d-a42b-edbabcbc10a2'::uuid, 'd475de7b-3705-5f2e-aea5-798a99b33ab3'::uuid, 1, '浙江适用杂草：大刺儿菜（大蓟）', '{"kind":"weed","item_id":"zj-weed-r73","weed_name":"大刺儿菜（大蓟）","canonical_name":"大刺儿菜","scientific_name":"Cirsium japonicum","family_genus":"菊科·蓟属","companion_crops":["小麦","玉米","果园","非耕地"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","陕西","辽宁","台湾"],"growth_stages_text":"① 根茎期：具粗壮根茎；② 幼苗期：叶片基生呈莲座状、羽状深裂带刺；③ 旺长期：茎直立、株高50～150cm；④ 开花期：头状花序大、紫红色；⑤ 结实期：具白色冠毛、随风传播。","best_control_stage_text":"莲座期至抽茎初期。","spray_window_text":"麦田返青期处理；果园与非耕地莲座期定向处理；配合深翻。","identification_key_text":"植株比刺儿菜高大粗壮、叶裂更深、刺更粗硬；头状花序更大；根茎粗壮。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":73,"cell_range":"A73:I73","row_sha256":"52e30838043123b94af8c0e56ed144a04118856e860e141caaeeb6ebdf5bce07","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=73;cells=A73:I73"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('1b374f22-65cd-5d3f-a640-8abf3d58034f'::uuid, '80f87b79-7624-53e0-89a7-b21e0b7e0093'::uuid, 1, '浙江适用杂草：苦苣菜', '{"kind":"weed","item_id":"zj-weed-r75","weed_name":"苦苣菜","canonical_name":"苦苣菜","scientific_name":"Sonchus oleraceus","family_genus":"菊科·苦苣菜属","companion_crops":["蔬菜","小麦","玉米","油菜","果园"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","陕西","辽宁","台湾"],"growth_stages_text":"① 幼苗期：叶片基生、羽状深裂、边缘带刺状齿；② 旺长期：茎直立、株高30～100cm、有乳汁；③ 开花期：头状花序黄色；④ 结实期：具白色冠毛。","best_control_stage_text":"莲座期至抽茎初期。","spray_window_text":"蔬菜与旱作田早期处理；果园定向处理。","identification_key_text":"叶片羽状深裂、裂片边缘有尖锐刺状齿（比苣荬菜裂得更深更尖）；茎生叶基部有明显耳状抱茎；折断有白色乳汁；头状花序黄色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":75,"cell_range":"A75:I75","row_sha256":"99527f2ddcf1a943e617b072b676aa8238d66e032189c8c981317e7b27d3e1bf","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=75;cells=A75:I75"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('ba604f82-2428-5e61-a8cc-3bc9b65d440e'::uuid, 'b077073c-0047-5466-81fa-8e2ae6c9f127'::uuid, 1, '浙江适用杂草：续断菊（花叶滇苦菜）', '{"kind":"weed","item_id":"zj-weed-r76","weed_name":"续断菊（花叶滇苦菜）","canonical_name":"续断菊","scientific_name":"Sonchus asper","family_genus":"菊科·苦苣菜属","companion_crops":["蔬菜","小麦","油菜","果园"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","福建","广东","广西","四川","云南","河南","山东","陕西","台湾"],"growth_stages_text":"① 幼苗期：叶片基生、边缘带硬刺；② 旺长期：茎直立、株高30～80cm；③ 开花期：头状花序黄色；④ 结实期：具白色冠毛。","best_control_stage_text":"莲座期至抽茎初期。","spray_window_text":"蔬菜与旱作田早期处理；果园定向处理。","identification_key_text":"叶片边缘具坚硬刺状齿（比苦苣菜更硬更扎手）、叶面有光泽；基部叶抱茎；折断有白色乳汁。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":76,"cell_range":"A76:I76","row_sha256":"ff116703bc47684605e48ef3ec233361175e54139f4f40ea46e290f06aeac396","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=76;cells=A76:I76"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('2080121b-e735-5bd8-92be-29bf3149ace7'::uuid, '6471f991-01e1-5b1d-b4d5-ac72b8ca83f6'::uuid, 1, '浙江适用杂草：蒲公英', '{"kind":"weed","item_id":"zj-weed-r77","weed_name":"蒲公英","canonical_name":"蒲公英","scientific_name":"Taraxacum mongolicum","family_genus":"菊科·蒲公英属","companion_crops":["果园","茶园","蔬菜","草坪","非耕地"],"distribution_note":"","distribution_provinces":["河北","河南","山东","山西","陕西","甘肃","辽宁","吉林","黑龙江","内蒙古","江苏","安徽","湖北","湖南","浙江","福建","四川","云南","贵州","青海","新疆","台湾"],"growth_stages_text":"① 莲座期：叶片全部基生呈莲座状、倒披针形羽状裂；② 返青期：早春由肉质根萌发；③ 开花期：头状花序黄色、花葶中空、单生；④ 结实期：果实具白色冠毛、形成「绒球」随风传播；⑤ 越冬期：肉质根越冬。","best_control_stage_text":"莲座期（返青后至抽葶前）。蒲公英一旦抽葶结籽，冠毛随风传播会大幅扩大发生面积，必须在开花前处理。","spray_window_text":"果园、茶园、草坪在莲座期定向处理；结合人工挖除肉质根（须挖净，残根可再生）。","identification_key_text":"叶片全部基生呈莲座状、羽状深裂、裂片呈齿状；花葶中空、单生头状花序、花黄色；果实带白色冠毛形成绒球；地下肉质根肥厚、断根可再生。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":77,"cell_range":"A77:I77","row_sha256":"0d58f84c3e13e90b4fb0bb0ca086e34cc95174a19f4281c615996b53f3e39328","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=77;cells=A77:I77"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('f6c45335-1401-52e6-8e4e-4775ea545de1'::uuid, '4ee39939-4e1a-57db-84bc-73cb701a0ba4'::uuid, 1, '浙江适用杂草：苍耳', '{"kind":"weed","item_id":"zj-weed-r78","weed_name":"苍耳","canonical_name":"苍耳","scientific_name":"Xanthium sibiricum","family_genus":"菊科·苍耳属","companion_crops":["玉米","大豆","棉花","花生","向日葵","蔬菜","果园"],"distribution_note":"全国各省份均有分布","distribution_provinces":["北京","天津","河北","山西","内蒙古","辽宁","吉林","黑龙江","上海","江苏","浙江","安徽","福建","江西","山东","河南","湖北","湖南","广东","广西","重庆","四川","贵州","云南","陕西","甘肃","宁夏","新疆","台湾"],"growth_stages_text":"① 幼苗期：下胚轴粗壮、子叶大、带紫红色；② 苗期：叶片三角状卵形、边缘有不规则粗齿、表面粗糙有毛；③ 旺长期：株高30～150cm、茎粗壮有紫斑、多分枝；④ 开花期：头状花序单性、雌花序藏于总苞内；⑤ 结实期：总苞硬化成具钩刺的「苍耳子」、极易粘附人畜衣物传播。","best_control_stage_text":"2～4叶期幼苗阶段。苍耳幼苗期后生长极快、株型高大且带刺总苞会刺伤人员并粘附农机，必须在幼苗期解决。","spray_window_text":"旱作田播后苗前封闭加苗后2～4叶期茎叶处理；果园在幼苗期施药；收获后清理带刺总苞（防止混入种子）。","identification_key_text":"叶片三角状卵形、边缘有不规则粗齿、两面粗糙有硬毛；幼苗下胚轴粗壮带紫红色（是田间快速识别点）；果实（苍耳子）密生钩刺、极易粘附衣物。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":78,"cell_range":"A78:I78","row_sha256":"c886fdc4baaf9f14a4670eec10fb2bfa35cd1f003fa47d4a8b68c6b4c5314d28","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=78;cells=A78:I78"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('13b1f7bc-57d7-556e-92ce-7e2214d23ecf'::uuid, 'f49d7e76-1215-52c9-8be4-95ada0c98648'::uuid, 1, '浙江适用杂草：鳢肠（旱莲草）', '{"kind":"weed","item_id":"zj-weed-r79","weed_name":"鳢肠（旱莲草）","canonical_name":"鳢肠","scientific_name":"Eclipta prostrata","family_genus":"菊科·鳢肠属","companion_crops":["水稻","大豆","蔬菜","棉花","果园","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","重庆","云南","贵州","河南","山东","陕西","台湾"],"growth_stages_text":"① 幼苗期：茎匍匐或斜升、叶片对生；② 营养生长期：茎匍匐蔓延、节上生根、植株多毛；③ 开花期：头状花序小、白色、单生叶腋或枝顶；④ 结实期：种子小、黑色。","best_control_stage_text":"幼苗期至营养生长前期。鳢肠匍匐茎节上生根、再生力强，须在蔓延前处理。","spray_window_text":"稻田与湿地农田早期处理；大豆、蔬菜田苗前封闭加苗后早期处理；果园定向处理。","identification_key_text":"全株密生白色糙毛；茎匍匐或斜升、节上生根、折断后汁液变黑（故名「鳢肠/墨旱莲」）；叶片对生、披针形有齿；头状花序小、白色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":79,"cell_range":"A79:I79","row_sha256":"3a66dc80477581fc6f9812196d8375e7160883ea5f51e4c07a593cb8229649fc","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=79;cells=A79:I79"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('1dfbc8bb-5e82-5fe8-b8bb-0e986c9949ef'::uuid, '1853228f-c082-5aaa-b8d9-d47a6505c788'::uuid, 1, '浙江适用杂草：胜红蓟（藿香蓟）', '{"kind":"weed","item_id":"zj-weed-r80","weed_name":"胜红蓟（藿香蓟）","canonical_name":"胜红蓟","scientific_name":"Ageratum conyzoides","family_genus":"菊科·藿香蓟属","companion_crops":["甘蔗","果园","茶园","蔬菜","木薯","非耕地"],"distribution_note":"","distribution_provinces":["福建","广东","广西","海南","云南","贵州","四川","江西","湖南","浙江","台湾"],"growth_stages_text":"① 幼苗期：全株有毛、叶片对生卵形；② 旺长期：株高30～100cm、茎粗壮、多分枝；③ 开花期：头状花序小、淡紫色或白色、密集成伞房状；④ 结实期：种子极小、带冠毛、随风和水传播。","best_control_stage_text":"幼苗期至旺长期前。胜红蓟在华南繁殖极快、种子量极大，须在开花前压低基数。","spray_window_text":"甘蔗田、果园、茶园在幼苗期施药；结合中耕与覆盖；开花前必须清除，防止种子扩散。","identification_key_text":"全株密生白色柔毛、有特殊气味（揉碎气味明显）；头状花序小、淡紫色或白色、密集成伞房状；叶片对生、卵形、基部圆钝有3条明显主脉。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":80,"cell_range":"A80:I80","row_sha256":"1829b301d6f8d157f496ad0d836025bea912988aef6dbf335d81de98b43e33f8","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=80;cells=A80:I80"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('cabc1987-b959-51b1-a10c-29dcd3df71a7'::uuid, '657c5285-9bb0-5af2-b18a-d15becc8bd1c'::uuid, 1, '浙江适用杂草：豚草', '{"kind":"weed","item_id":"zj-weed-r82","weed_name":"豚草","canonical_name":"豚草","scientific_name":"Ambrosia artemisiifolia","family_genus":"菊科·豚草属","companion_crops":["玉米","大豆","蔬菜","果园","非耕地","路边"],"distribution_note":"","distribution_provinces":["辽宁","吉林","黑龙江","河北","北京","天津","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","四川","云南","陕西","新疆"],"growth_stages_text":"① 幼苗期：叶片对生、羽状深裂、有毛；② 旺长期：株高30～150cm、茎粗壮、上部叶互生；③ 开花期：头状花序单性、雄花序呈穗状下垂、雌花序腋生；④ 结实期：种子（瘦果）坚硬、具刺状突起，可存活数十年。","best_control_stage_text":"幼苗期（株高20cm以内）。豚草花粉是重要致敏原（引发花粉症），必须在开花散粉前彻底清除，否则既危害农业又危害公众健康。","spray_window_text":"在幼苗期施药或人工连根拔除；开花前必须完成清除；荒地、路边同步治理；接触植株时应佩戴口罩手套（防花粉过敏）。","identification_key_text":"叶片羽状深裂（形似艾蒿但更细裂）、两面有糙毛；上部叶互生、下部叶对生；雄花序呈穗状下垂、黄绿色（散粉时大量花粉飞扬）；全株有强烈气味。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":82,"cell_range":"A82:I82","row_sha256":"0b88e4c535178356e3e7cbdf58cb171e2c84d3a8415e6aa1489461f7d75c9de5","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=82;cells=A82:I82"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('25fc34a7-878f-5848-bfc9-762d5c378b35'::uuid, '4ea4ca0b-9ff0-56ab-943c-f40f534604ae'::uuid, 1, '浙江适用杂草：三叶鬼针草（鬼针草）', '{"kind":"weed","item_id":"zj-weed-r83","weed_name":"三叶鬼针草（鬼针草）","canonical_name":"三叶鬼针草","scientific_name":"Bidens pilosa","family_genus":"菊科·鬼针草属","companion_crops":["玉米","大豆","棉花","蔬菜","果园","甘蔗"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","重庆","云南","贵州","河南","山东","陕西","台湾"],"growth_stages_text":"① 幼苗期：叶片对生、羽状分裂；② 旺长期：株高30～100cm、茎四棱形；③ 开花期：头状花序、舌状花白色、管状花黄色；④ 结实期：瘦果细长、顶端具2～4枚倒刺（芒刺），极易粘附人畜衣物。","best_control_stage_text":"幼苗期至旺长初期。鬼针草结实后带倒刺的种子随人畜、农机广泛传播，必须在开花前清除。","spray_window_text":"玉米、大豆、蔬菜田苗前封闭加苗后早期处理；果园在幼苗期施药；开花前必须清除。","identification_key_text":"瘦果顶端具2～4枚倒刺状芒（粘附衣物，是传播与识别关键）；头状花序舌状花白色、管状花黄色；茎四棱形、常带紫色；叶片对生、羽状分裂。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":83,"cell_range":"A83:I83","row_sha256":"c373588c9881726ca6dd99fdb076a5e47480684defc847b873a9ca4aed54b5c8","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=83;cells=A83:I83"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('4c9cd81a-9a70-5238-84ba-e070b381341a'::uuid, '9b4c7c94-8047-5e60-a146-d6082fa0a9d4'::uuid, 1, '浙江适用杂草：大狼把草', '{"kind":"weed","item_id":"zj-weed-r84","weed_name":"大狼把草","canonical_name":"大狼把草","scientific_name":"Bidens frondosa","family_genus":"菊科·鬼针草属","companion_crops":["水稻田边","大豆","玉米","蔬菜","湿地"],"distribution_note":"","distribution_provinces":["辽宁","吉林","黑龙江","河北","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南"],"growth_stages_text":"① 幼苗期：叶片对生、羽状复叶；② 旺长期：株高30～120cm、茎粗壮；③ 开花期：头状花序无舌状花、全为管状花；④ 结实期：瘦果扁平、顶端具2枚倒刺。","best_control_stage_text":"幼苗期至旺长初期。","spray_window_text":"稻田边与旱作田早期处理；开花前清除。","identification_key_text":"头状花序无舌状花（与三叶鬼针草的区别）、全为黄褐色管状花；叶为羽状复叶、小叶3～5枚；瘦果扁平、具2枚倒刺。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":84,"cell_range":"A84:I84","row_sha256":"e6cb6e31d4d3896594af074fe18f2ebe801bcabc7b3330b5bbc4f83f1766d7ab","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=84;cells=A84:I84"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_soybean","crop_corn"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('02411d0a-1008-590a-9343-36c1a7d24427'::uuid, 'a110944f-89d3-5e00-90e4-f8fd166ab928'::uuid, 1, '浙江适用杂草：小蓬草（加拿大蓬）', '{"kind":"weed","item_id":"zj-weed-r85","weed_name":"小蓬草（加拿大蓬）","canonical_name":"小蓬草","scientific_name":"Conyza canadensis","family_genus":"菊科·白酒草属","companion_crops":["小麦","玉米","大豆","果园","茶园","非耕地"],"distribution_note":"全国广布","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","贵州","陕西","甘肃","辽宁","吉林","黑龙江","新疆","台湾"],"growth_stages_text":"① 莲座期：幼苗叶片基生呈莲座状、全缘或有疏齿、有毛；② 抽茎期：茎直立、株高50～150cm、有纵棱和毛；③ 开花期：头状花序极小极多、白色、密集成圆锥状；④ 结实期：种子带白色冠毛、随风远距离传播。","best_control_stage_text":"莲座期至抽茎初期（株高15cm以内）。小蓬草结实后冠毛随风传播、种子量极大，一旦开花即失去防治意义。","spray_window_text":"麦田、玉米田苗后早期处理；果园、茶园在莲座期定向处理；非耕地苗期施药；开花前必须清除。","identification_key_text":"幼苗基生呈莲座状、全缘或有疏齿、被白色粗毛；成株茎直立有纵棱、全株灰绿色；头状花序极小极多、白色、密集；种子带白色冠毛。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":85,"cell_range":"A85:I85","row_sha256":"d355c67bba4a21ce49c03f07ba63e7b6ba4d8ebc7d7b142ed571dd362b293a60","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=85;cells=A85:I85"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('d75c1b97-8a2e-5d08-95e2-129d726c9dad'::uuid, '4324caa6-adb9-57ff-9b87-9774579c8f23'::uuid, 1, '浙江适用杂草：一年蓬', '{"kind":"weed","item_id":"zj-weed-r86","weed_name":"一年蓬","canonical_name":"一年蓬","scientific_name":"Erigeron annuus","family_genus":"菊科·飞蓬属","companion_crops":["小麦","果园","茶园","蔬菜","非耕地"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","云南","贵州","河南","山东","陕西","河北","辽宁","台湾"],"growth_stages_text":"① 莲座期：幼苗基生叶呈莲座状、有毛；② 抽茎期：茎直立、株高30～100cm、有毛；③ 开花期：头状花序、舌状花白色、管状花黄色、多数排列成伞房状；④ 结实期：种子带冠毛、随风传播。","best_control_stage_text":"莲座期至抽茎初期。","spray_window_text":"果园、茶园在莲座期处理；麦田早期处理；开花前清除。","identification_key_text":"头状花序舌状花白色（略带淡紫）、管状花黄色、花径约1.5cm（花序明显大于小蓬草）；全株有毛；基生叶莲座状。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":86,"cell_range":"A86:I86","row_sha256":"3c19c00f141e731895c682b8e8889e75ee4bb379bfb36dc858791978e8f9db74","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=86;cells=A86:I86"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('f033f867-f0b7-5032-8116-204ebb7cc216'::uuid, 'aca94b22-0492-53f9-a3bc-bbfd5c95419f'::uuid, 1, '浙江适用杂草：香丝草（野塘蒿）', '{"kind":"weed","item_id":"zj-weed-r87","weed_name":"香丝草（野塘蒿）","canonical_name":"香丝草","scientific_name":"Conyza bonariensis","family_genus":"菊科·白酒草属","companion_crops":["小麦","玉米","果园","非耕地"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","陕西","台湾"],"growth_stages_text":"① 莲座期：幼苗基生叶、密生灰白毛；② 抽茎期：茎直立、株高30～80cm、多分枝；③ 开花期：头状花序小、白色略带淡紫；④ 结实期：种子带冠毛、随风传播。","best_control_stage_text":"莲座期至抽茎初期。","spray_window_text":"麦田与果园早期处理；开花前清除。","identification_key_text":"全株密生灰白色柔毛、呈灰绿色；植株比小蓬草矮小、分枝多；头状花序小、白色略带淡紫；叶片狭长。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":87,"cell_range":"A87:I87","row_sha256":"c38392d03097f57930c288868b9afb9365355352518b43879f4825882a85535f","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=87;cells=A87:I87"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('7ead9b3d-2a3b-5f9d-b8e5-4f137b40ed5d'::uuid, 'e58c701b-c664-5554-a922-c527689feeaf'::uuid, 1, '浙江适用杂草：荠菜（荠）', '{"kind":"weed","item_id":"zj-weed-r89","weed_name":"荠菜（荠）","canonical_name":"荠菜","scientific_name":"Capsella bursa-pastoris","family_genus":"十字花科·荠属","companion_crops":["小麦","油菜","蔬菜","果园"],"distribution_note":"全国各省份均有分布","distribution_provinces":["北京","天津","河北","山西","内蒙古","辽宁","吉林","黑龙江","上海","江苏","浙江","安徽","福建","江西","山东","河南","湖北","湖南","广东","广西","重庆","四川","贵州","云南","西藏","陕西","甘肃","青海","宁夏","新疆","台湾"],"growth_stages_text":"① 幼苗期：子叶小、基生叶羽状分裂；② 莲座期：叶片基生成莲座状、羽状深裂、鲜绿色无毛；③ 抽薹期：株高10～50cm、茎直立有分枝；④ 开花期：花小、白色、总状花序；⑤ 结实期：短角果呈倒三角形（形如小钱包，是识别关键）、种子细小。","best_control_stage_text":"莲座期至抽薹初期（株高10cm以内）。荠菜抽薹开花极早（南方2月即可抽薹），必须在抽薹前防除。","spray_window_text":"小麦播后苗前封闭；冬前或返青期茎叶处理；蔬菜田须注意采摘安全间隔。","identification_key_text":"基生叶莲座状、羽状深裂、鲜绿无毛（区别于播娘蒿的灰绿有毛）；短角果倒三角形、扁平如小钱包（最可靠识别特征）；花白色、极小。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":89,"cell_range":"A89:I89","row_sha256":"c706486246582fea2f91a05cf0a830c781f627c8203fdd5c5f5149571b37e345","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=89;cells=A89:I89"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('239c301f-89ff-5ec6-929e-f46d69128b20'::uuid, '5327e4f8-fa75-5b8f-bb59-a51d22e580e0'::uuid, 1, '浙江适用杂草：繁缕（鹅肠菜）', '{"kind":"weed","item_id":"zj-weed-r93","weed_name":"繁缕（鹅肠菜）","canonical_name":"繁缕","scientific_name":"Stellaria media","family_genus":"石竹科·繁缕属","companion_crops":["小麦","蔬菜","油菜","果园","绿肥"],"distribution_note":"全国广布","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","河南","山东","河北","陕西","四川","重庆","贵州","云南","福建","广西","辽宁","吉林","黑龙江","新疆","台湾"],"growth_stages_text":"① 幼苗期：茎纤细匍匐、叶片卵形对生；② 营养生长期：茎匍匐蔓延、节上生根、形成密集草层；③ 开花期：花极小、白色、星形（5枚深裂花瓣看似10枚）；④ 结实期：蒴果小、种子极多。","best_control_stage_text":"幼苗期至营养生长前期（草层未封行前）。繁缕匍匐茎节上生根、再生力强，一旦形成草层就极难彻底防除。","spray_window_text":"小麦播后苗前封闭；冬前或返青期茎叶处理；蔬菜田早期处理。","identification_key_text":"茎纤细、匍匐地面、节上生根、茎上有一行纵向细毛（用放大镜观察）；叶片卵形、对生、全缘；花极小、白色、5枚花瓣各深裂为2，看似10枚花瓣（是石竹科典型特征）。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":93,"cell_range":"A93:I93","row_sha256":"ebd485e8ed0dfe3c1badb237ec18feaf649dd43d7cf157dd6731b85d3fd6e392","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=93;cells=A93:I93"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('860be9b4-35c1-5c46-8050-830da53c5ef3'::uuid, '0ff14518-3188-544e-9499-5dfcd85abac1'::uuid, 1, '浙江适用杂草：牛繁缕（鹅儿肠）', '{"kind":"weed","item_id":"zj-weed-r94","weed_name":"牛繁缕（鹅儿肠）","canonical_name":"牛繁缕","scientific_name":"Myosoton aquaticum","family_genus":"石竹科·牛繁缕属","companion_crops":["小麦","油菜","蔬菜","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","河南","山东","四川","云南","贵州","陕西","河北","福建","广西"],"growth_stages_text":"① 幼苗期：茎较粗、带紫红；② 营养生长期：茎匍匐或上升、节上生根；③ 开花期：花白色、5枚花瓣各深裂为2（与繁缕相似但花较大）；④ 结实期：蒴果、种子多。","best_control_stage_text":"幼苗期至营养生长前期。","spray_window_text":"稻茬麦田与油菜田冬前处理；喜湿，注意田间排水。","identification_key_text":"花明显比繁缕大（花径约1cm，繁缕约0.5cm）；茎较粗、常带紫红色、光滑无纵毛（繁缕茎上有一行细毛）；叶片较大、卵状心形。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":94,"cell_range":"A94:I94","row_sha256":"a21f0df0d122aa832d8b6fdf5a62a20fb9eab6cd3609c451461d00417957cd0d","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=94;cells=A94:I94"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('04eed868-1678-5b94-8e3f-db8c7954f5ef'::uuid, '220cac0c-5d38-5d39-ae4c-560a02fd3d5d'::uuid, 1, '浙江适用杂草：婆婆纳', '{"kind":"weed","item_id":"zj-weed-r95","weed_name":"婆婆纳","canonical_name":"婆婆纳","scientific_name":"Veronica didyma","family_genus":"车前科（原玄参科）·婆婆纳属","companion_crops":["小麦","油菜","蔬菜","果园"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","河南","山东","河北","陕西","四川","云南","贵州","福建","广西","北京","天津"],"growth_stages_text":"① 幼苗期：茎匍匐、叶片三角状卵形有齿；② 营养生长期：茎匍匐蔓延、节上生根；③ 开花期：花小、淡蓝紫色、具放射状深色条纹、单生叶腋；④ 结实期：蒴果扁圆、种子小。","best_control_stage_text":"幼苗期至营养生长前期。婆婆纳植株矮小贴地、常被忽略，须在开花前及早处理。","spray_window_text":"小麦播后苗前封闭；冬前茎叶处理（选用对婆婆纳有效的药剂，如唑草酮、2甲4氯复配）。","identification_key_text":"花小、淡蓝紫色、具放射状深色条纹（形似小眼睛，是识别捷径）；茎匍匐、节上生根；叶片三角状卵形、边缘有圆齿、对生。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":95,"cell_range":"A95:I95","row_sha256":"9e4ea493eb924571aaf1f2c20660ad62129324bccf0ba5d0894748f17595db4d","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=95;cells=A95:I95"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('71c733ba-d1e3-5a53-a473-e821c4bb4844'::uuid, 'c0af321b-7ead-578f-a669-91149731ad6b'::uuid, 1, '浙江适用杂草：阿拉伯婆婆纳', '{"kind":"weed","item_id":"zj-weed-r96","weed_name":"阿拉伯婆婆纳","canonical_name":"阿拉伯婆婆纳","scientific_name":"Veronica persica","family_genus":"车前科（原玄参科）·婆婆纳属","companion_crops":["小麦","油菜","蔬菜","果园"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","河南","山东","陕西","四川","云南","贵州","福建","广西","河北"],"growth_stages_text":"① 幼苗期：茎匍匐、叶片卵形有齿、有毛；② 营养生长期：茎匍匐蔓延；③ 开花期：花较大、蓝色具深色条纹、花梗长于苞片；④ 结实期：蒴果扁圆、具网纹。","best_control_stage_text":"幼苗期至营养生长前期。","spray_window_text":"麦田冬前处理；油菜田早期处理。","identification_key_text":"花比婆婆纳更大、蓝色更深、花梗明显长于苞片（婆婆纳花梗短于苞片）；蒴果表面有明显网纹；全株有毛。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":96,"cell_range":"A96:I96","row_sha256":"3184a64e3d734706d82a37235dd491ebae475a67258290ab519219befb3b98e4","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=96;cells=A96:I96"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('f0624f33-f684-51e1-995f-f9748f852d10'::uuid, 'af0d891a-679b-5e2f-9a1e-5e70b840b0eb'::uuid, 1, '浙江适用杂草：泽漆（五朵云）', '{"kind":"weed","item_id":"zj-weed-r97","weed_name":"泽漆（五朵云）","canonical_name":"泽漆","scientific_name":"Euphorbia helioscopia","family_genus":"大戟科·大戟属","companion_crops":["小麦","油菜","蔬菜","果园"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","河南","山东","河北","陕西","四川","云南","贵州","福建","广西","山西","甘肃"],"growth_stages_text":"① 幼苗期：茎带紫红、叶片倒卵形；② 莲座期：基生叶丛生；③ 抽茎期：株高10～30cm、茎直立、顶部有5枚轮生苞叶呈伞状（「五朵云」得名）；④ 开花期：杯状聚伞花序、黄绿色；⑤ 结实期：蒴果三棱状、种子有网纹。","best_control_stage_text":"莲座期至抽茎初期（顶部伞状苞叶形成前）。泽漆乳汁有毒，接触皮肤可致红肿过敏，作业须做好防护。","spray_window_text":"麦田冬前或返青期茎叶处理；油菜田早期处理；作业时戴手套，避免乳汁接触皮肤和眼睛。","identification_key_text":"茎顶有5枚轮生苞叶呈伞状展开（形如「五朵云」，是最直观特征）；折断茎叶流出白色乳汁（有毒，勿触眼）；全株黄绿色；蒴果三棱状。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":97,"cell_range":"A97:I97","row_sha256":"a9dc9583c583d4edf3d826cae10c5740ab26414869b1d5bb007e695dc005b341","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=97;cells=A97:I97"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('ec9f7c5d-29c3-5c3f-a7df-79cc64ed240e'::uuid, 'a8b36e20-23b7-5907-9e0d-dd100c8fb2ba'::uuid, 1, '浙江适用杂草：风花菜（蔊菜）', '{"kind":"weed","item_id":"zj-weed-r98","weed_name":"风花菜（蔊菜）","canonical_name":"风花菜","scientific_name":"Rorippa palustris","family_genus":"十字花科·蔊菜属","companion_crops":["小麦","油菜","蔬菜","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","河南","山东","河北","四川","云南","贵州","陕西","福建","广西","黑龙江","辽宁"],"growth_stages_text":"① 幼苗期：叶片羽状分裂；② 莲座期：基生叶丛生；③ 抽薹期：株高20～60cm、茎直立多分枝；④ 开花期：花小、黄色、总状花序；⑤ 结实期：长角果圆柱形、种子小。","best_control_stage_text":"莲座期至抽薹初期。","spray_window_text":"麦田与油菜田冬前或返青期处理；喜湿，注意排水。","identification_key_text":"花小、黄色、总状花序（与播娘蒿相似但全株无灰白毛、鲜绿色）；长角果短圆柱形而非细长；叶片羽状分裂但裂片较宽。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":98,"cell_range":"A98:I98","row_sha256":"13d2346c30cdad0e6cf79099f9c309f9b033daefcdd647ddd28217ebb1cfda9a","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=98;cells=A98:I98"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('5c5fdbcd-185e-51ef-8c27-cb8c1e504055'::uuid, 'f1f3c87f-e8dd-510c-8283-9cb64d5365e7'::uuid, 1, '浙江适用杂草：宝盖草', '{"kind":"weed","item_id":"zj-weed-r101","weed_name":"宝盖草","canonical_name":"宝盖草","scientific_name":"Lamium amplexicaule","family_genus":"唇形科·野芝麻属","companion_crops":["小麦","油菜","蔬菜","果园"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","河南","山东","河北","陕西","四川","云南","贵州","福建","广西","甘肃"],"growth_stages_text":"① 幼苗期：茎四棱、叶片对生；② 营养生长期：茎匍匐或上升；③ 开花期：花唇形、紫红色、轮生于茎顶；④ 结实期：小坚果三棱状、种子小。","best_control_stage_text":"幼苗期至营养生长前期。","spray_window_text":"麦田冬前处理；油菜田与蔬菜田早期处理。","identification_key_text":"茎四棱形（唇形科典型特征）；上部叶片无柄、基部抱茎呈「宝盖」状（故名）；花唇形、紫红色、轮生于茎顶；全株有毛。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":101,"cell_range":"A101:I101","row_sha256":"b63f42c57d4efe375864a9e32758094730bde222159809304fd7e83e84798209","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=101;cells=A101:I101"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('684ab1f2-3dff-5602-9848-4be34bec91a0'::uuid, 'd239b67b-7716-5de8-90b7-c6dce34971d4'::uuid, 1, '浙江适用杂草：猪殃殃', '{"kind":"weed","item_id":"zj-weed-r102","weed_name":"猪殃殃","canonical_name":"猪殃殃","scientific_name":"Galium aparine","family_genus":"茜草科·拉拉藤属","companion_crops":["小麦","油菜","蔬菜","果园"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","河南","山东","河北","陕西","四川","云南","贵州","山西","甘肃","辽宁","黑龙江","新疆"],"growth_stages_text":"① 幼苗期：茎四棱、纤细、带倒刺；② 营养生长期：茎蔓生攀援、四棱上有倒刺毛（可附着作物向上攀爬）、形成缠绕层；③ 开花期：花极小、黄绿色、聚伞花序；④ 结实期：果实为2枚球形小坚果、表面密生钩刺，极易粘附衣物和动物皮毛。","best_control_stage_text":"幼苗期至蔓生初期（尚未攀附作物时）。猪殃殃一旦攀附作物形成缠绕层，既与作物争光又妨碍收割，且施药难以覆盖，必须在早期处理。","spray_window_text":"小麦播后苗前封闭；冬前或返青期茎叶处理（选用氯氟吡氧乙酸、唑草酮等）；油菜田注意选药。","identification_key_text":"茎四棱形、棱上密生倒刺毛（手感明显扎手、能粘附衣物）；叶片6～8枚轮生；果实为2枚球形小坚果、密生钩刺（「猪殃殃」得名，可粘附衣物传播）。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":102,"cell_range":"A102:I102","row_sha256":"c023816ffaf8cc0e64c52851daff04087bc4a96ccddf5d50e517f08f605c482e","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=102;cells=A102:I102"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('642653c4-b069-55e7-a6c4-94d6a552ab61'::uuid, '49e203e0-3830-50e8-9181-f9c3002f0096'::uuid, 1, '浙江适用杂草：拉拉藤', '{"kind":"weed","item_id":"zj-weed-r103","weed_name":"拉拉藤","canonical_name":"拉拉藤","scientific_name":"Galium spurium","family_genus":"茜草科·拉拉藤属","companion_crops":["小麦","油菜","蔬菜"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","河南","山东","河北","陕西","四川","云南","山西","甘肃","辽宁","黑龙江"],"growth_stages_text":"① 幼苗期：茎四棱细弱；② 营养生长期：蔓生攀援、四棱有倒刺；③ 开花期：花极小、黄绿色；④ 结实期：小坚果有钩刺。","best_control_stage_text":"幼苗期至蔓生初期。","spray_window_text":"麦田冬前或返青期处理。","identification_key_text":"与猪殃殃极相似，区别在于拉拉藤叶片通常6枚轮生、植株较细弱、果实钩刺较短；同样四棱茎带倒刺、可粘附衣物。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":103,"cell_range":"A103:I103","row_sha256":"90b05595e61d5ebaac4e0405568ec9e43cd072273283d464d4406158970a3bc9","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=103;cells=A103:I103"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('ac7e70a6-91e1-550f-98fb-7065b6e2362f'::uuid, '297f2ff0-1f79-5d9d-9fdd-36c5de66f7fc'::uuid, 1, '浙江适用杂草：野老鹳草', '{"kind":"weed","item_id":"zj-weed-r105","weed_name":"野老鹳草","canonical_name":"野老鹳草","scientific_name":"Geranium carolinianum","family_genus":"牻牛儿苗科·老鹳草属","companion_crops":["小麦","油菜","蔬菜","果园"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","河南","山东","四川","云南","贵州","陕西","福建","广西"],"growth_stages_text":"① 幼苗期：叶片掌状分裂、基生呈莲座状；② 莲座期：叶片基生丛生、全株有毛；③ 抽茎期：株高20～60cm、茎直立多分枝；④ 开花期：花小、粉红色、5瓣；⑤ 结实期：蒴果具长喙（形如老鹳之嘴，故名）、成熟后5瓣向上开裂卷曲、种子弹射传播。","best_control_stage_text":"莲座期至抽茎初期。","spray_window_text":"麦田冬前或返青期茎叶处理；油菜田早期处理。","identification_key_text":"叶片掌状深裂（形似掌状）、全株有毛；蒴果具细长喙状结构、成熟后5个果瓣向上卷曲如老鹳嘴（最典型特征）；花小、粉红色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":105,"cell_range":"A105:I105","row_sha256":"a9c8dc575ed5ae91cc0daa2384f7f98985348761198243f69d69cd0a6453d217","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=105;cells=A105:I105"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('ffcc024e-9648-55ea-86e1-b801bfe96994'::uuid, '312a2cbd-9aaa-5683-bf7b-12a83028ab4e'::uuid, 1, '浙江适用杂草：通泉草', '{"kind":"weed","item_id":"zj-weed-r106","weed_name":"通泉草","canonical_name":"通泉草","scientific_name":"Mazus japonicus","family_genus":"通泉草科（原玄参科）·通泉草属","companion_crops":["水稻","蔬菜","湿地农田","草坪"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","福建","广东","广西","四川","云南","贵州","河南","山东","陕西","台湾"],"growth_stages_text":"① 幼苗期：叶片基生呈莲座状、倒卵形有齿；② 营养生长期：花茎斜升、植株矮小；③ 开花期：花唇形、淡蓝紫色、下唇有黄色斑块；④ 结实期：蒴果小、种子极多。","best_control_stage_text":"莲座期至开花前。通泉草喜湿、常生于田埂和水田边，须与田内同步防除。","spray_window_text":"稻田边、蔬菜田与草坪在开花前处理；结合清除田埂杂草。","identification_key_text":"植株矮小、叶片基生呈莲座状、倒卵形有疏齿；花唇形、淡蓝紫色、下唇中央有黄色斑块（识别捷径）；喜湿、常见于田埂与湿地。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":106,"cell_range":"A106:I106","row_sha256":"65aeba0912995b0fce08989e154e20d942f95253b6db07727f64c8e6ae6f006e","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=106;cells=A106:I106"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('44cf52fc-92fc-5625-8db9-4e68ac2a530c'::uuid, 'c5634519-4481-5cc8-81ad-dd8962cfa2f8'::uuid, 1, '浙江适用杂草：陌上菜', '{"kind":"weed","item_id":"zj-weed-r107","weed_name":"陌上菜","canonical_name":"陌上菜","scientific_name":"Lindernia procumbens","family_genus":"母草科（原玄参科）·陌上菜属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","福建","广东","广西","四川","云南","河南","台湾"],"growth_stages_text":"① 幼苗期：茎匍匐、叶片对生；② 营养生长期：茎匍匐蔓延、节上生根；③ 开花期：花小、淡紫色、单生叶腋；④ 结实期：蒴果小、种子极多。","best_control_stage_text":"幼苗期至营养生长前期。陌上菜是稻田常见矮小杂草，须在稻田早期封闭处理时一并防除。","spray_window_text":"稻田移栽后5～10天土壤或早期茎叶处理。","identification_key_text":"茎匍匐、节上生根；叶片对生、椭圆形、全缘；花小、淡紫色、单生叶腋；植株矮小贴地。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":107,"cell_range":"A107:I107","row_sha256":"8113f8420e160c66089e529bebaa27147f7260626327f7576deeee74f953a1f0","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=107;cells=A107:I107"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('9880813d-2d16-51e3-90cf-0015548a47ed'::uuid, '36413afa-04cb-54f5-8b8e-8ab552d1bf02'::uuid, 1, '浙江适用杂草：水苦荬', '{"kind":"weed","item_id":"zj-weed-r108","weed_name":"水苦荬","canonical_name":"水苦荬","scientific_name":"Veronica undulata","family_genus":"车前科（原玄参科）·婆婆纳属","companion_crops":["水稻","湿地农田","沟渠边"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","福建","广东","广西","四川","云南","河南","山东","台湾"],"growth_stages_text":"① 幼苗期：茎直立、叶片对生；② 旺长期：株高20～60cm、茎肉质；③ 开花期：花小、淡蓝色、总状花序；④ 结实期：蒴果小、种子多。","best_control_stage_text":"幼苗期至旺长初期。","spray_window_text":"稻田与湿地早期处理；结合清沟。","identification_key_text":"喜水湿、茎肉质；叶片对生、披针形有齿；花小、淡蓝色、总状花序；蒴果成熟后常被虫寄生形成「虫瘿」而膨大。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":108,"cell_range":"A108:I108","row_sha256":"b3ba2557361aa62230768446adfb5dd55f37c243171844004c148f64fb37c243","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=108;cells=A108:I108"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('daf89ece-c8df-53b6-8c3c-ca3927a58155'::uuid, 'ad7bbc74-245a-56c4-b766-cd7bb51eecf2'::uuid, 1, '浙江适用杂草：附地菜', '{"kind":"weed","item_id":"zj-weed-r109","weed_name":"附地菜","canonical_name":"附地菜","scientific_name":"Trigonotis peduncularis","family_genus":"紫草科·附地菜属","companion_crops":["小麦","蔬菜","果园","草坪"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","四川","云南","陕西","山西","甘肃","辽宁","吉林","黑龙江","福建","广西"],"growth_stages_text":"① 幼苗期：叶片基生、卵形有毛；② 莲座期：基生叶丛生、全株有毛；③ 开花期：花极小、淡蓝色、总状花序（花序常呈蝎尾状卷曲）；④ 结实期：小坚果4枚、细小。","best_control_stage_text":"莲座期至开花前。","spray_window_text":"麦田、蔬菜田与草坪早期处理。","identification_key_text":"全株密生短糙毛；花极小、淡蓝色、总状花序顶端常呈蝎尾状卷曲；叶片基生卵形、有柄；植株矮小。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":109,"cell_range":"A109:I109","row_sha256":"311fcb43c524a51525b0eae4f69eed70dfb3b6c0c459c331d2ad26cf3652d864","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=109;cells=A109:I109"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('fb0e80c9-a6b1-5cbf-86d5-f1fc8dee2bb7'::uuid, 'c8f25a3a-2367-589b-9fd2-00aecf35a17e'::uuid, 1, '浙江适用杂草：香薷', '{"kind":"weed","item_id":"zj-weed-r112","weed_name":"香薷","canonical_name":"香薷","scientific_name":"Elsholtzia ciliata","family_genus":"唇形科·香薷属","companion_crops":["玉米","大豆","果园","蔬菜"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","贵州","陕西","辽宁","吉林","黑龙江","甘肃","新疆","台湾"],"growth_stages_text":"① 幼苗期：茎四棱、叶片对生卵形；② 旺长期：株高30～100cm、茎四棱、多分枝；③ 开花期：穗状花序顶生、偏向一侧、花小淡紫色；④ 结实期：小坚果细小、量多。","best_control_stage_text":"幼苗期至旺长初期。","spray_window_text":"玉米、大豆田苗后早期处理；果园定向处理。","identification_key_text":"全株有浓烈香气（揉碎气味明显，故名「香薷」）；穗状花序明显偏向一侧（是识别关键）；茎四棱形；叶片对生、卵形有齿。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":112,"cell_range":"A112:I112","row_sha256":"9ce4630c4501b82400066b995d7fa3b37f564b5b6e3090caaea2201fef6cec1f","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=112;cells=A112:I112"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('fb9cfd85-5ba6-520a-ac04-34b20540362f'::uuid, '2ed865e0-ffd6-579a-846d-3b2d36690d41'::uuid, 1, '浙江适用杂草：益母草', '{"kind":"weed","item_id":"zj-weed-r113","weed_name":"益母草","canonical_name":"益母草","scientific_name":"Leonurus japonicus","family_genus":"唇形科·益母草属","companion_crops":["小麦","油菜","果园","蔬菜"],"distribution_note":"全国广布","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","贵州","陕西","山西","甘肃","辽宁","吉林","黑龙江","新疆","台湾"],"growth_stages_text":"① 幼苗期：叶片基生、掌状分裂；② 莲座期：基生叶丛生；③ 抽茎期：株高30～120cm、茎四棱、多分枝；④ 开花期：花唇形、淡紫红色、轮生于叶腋；⑤ 结实期：小坚果三棱状、表面光滑。","best_control_stage_text":"莲座期至抽茎初期。","spray_window_text":"麦田与油菜田早期处理；果园定向处理。","identification_key_text":"茎四棱形、有纵沟；叶片掌状深裂（下部叶）至羽状分裂（上部叶）；花唇形、淡紫红色、轮生于叶腋形成「轮伞花序」；全株有香气。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":113,"cell_range":"A113:I113","row_sha256":"f0723bbc3062e4f55c74ef80dd3eef4b0eaafffe36903e2305fd505cb0652646","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=113;cells=A113:I113"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('f993f1b3-b732-57f9-9ddb-f1b1555f88f9'::uuid, '83ba90eb-ec7c-51b4-859c-2c8c17fc1d4d'::uuid, 1, '浙江适用杂草：酸模叶蓼（旱苗蓼）', '{"kind":"weed","item_id":"zj-weed-r114","weed_name":"酸模叶蓼（旱苗蓼）","canonical_name":"酸模叶蓼","scientific_name":"Polygonum lapathifolium","family_genus":"蓼科·蓼属","companion_crops":["水稻","大豆","玉米","蔬菜","湿地农田"],"distribution_note":"","distribution_provinces":["黑龙江","吉林","辽宁","河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","贵州","陕西","内蒙古","新疆","台湾"],"growth_stages_text":"① 幼苗期：茎直立、叶片披针形、茎节膨大；② 旺长期：株高30～150cm、茎粗壮、节明显膨大、茎常带红紫色；③ 开花期：穗状花序顶生或腋生、密生淡红色小花；④ 结实期：小坚果扁圆形、黑褐色有光泽、数量多。","best_control_stage_text":"幼苗期至旺长初期（株高20cm以内）。蓼属茎节膨大、再生力强，一旦形成高密度群落防效下降明显。","spray_window_text":"稻田移栽后早期处理；旱田播后苗前封闭加苗后早期处理；果园定向处理。","identification_key_text":"茎节明显膨大（形如竹节，是蓼属共同特征）；叶片披针形、表面常有暗色斑纹（故称「酸模叶」）；叶柄基部有膜质托叶鞘抱茎；穗状花序淡红色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":114,"cell_range":"A114:I114","row_sha256":"a145d023e5ca00762e3bdf085a8a2dabec4b1f321bc31a40e22c0e3231c3da72","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=114;cells=A114:I114"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_soybean","crop_corn"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('c9c22bf5-a3b4-5c0e-bae0-f232d8a4bf9e'::uuid, 'ccab9693-c164-51fd-9f25-de4598ab7044'::uuid, 1, '浙江适用杂草：齿果酸模', '{"kind":"weed","item_id":"zj-weed-r117","weed_name":"齿果酸模","canonical_name":"齿果酸模","scientific_name":"Rumex dentatus","family_genus":"蓼科·酸模属","companion_crops":["小麦","油菜","蔬菜","果园","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","河南","山东","河北","陕西","四川","云南","贵州","福建","广西","山西","甘肃"],"growth_stages_text":"① 幼苗期：叶片基生呈莲座状、长椭圆形；② 莲座期：基生叶丛生、有长柄；③ 抽茎期：株高30～100cm、茎直立有纵棱；④ 开花期：圆锥花序、花小绿色、轮生；⑤ 结实期：小坚果三棱状、边缘有齿状刺（「齿果」得名）。","best_control_stage_text":"莲座期至抽茎初期。酸模属根系为粗壮肉质直根、断根可萌发，须在莲座期处理并深挖除根。","spray_window_text":"麦田冬前或返青期处理；油菜田早期处理；果园在莲座期定向处理。","identification_key_text":"基生叶呈莲座状、长椭圆形、边缘波状；圆锥花序轮生、花小绿色；小坚果三棱状、边缘具齿状刺；具粗壮肉质直根。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":117,"cell_range":"A117:I117","row_sha256":"631f6d56b878ab8dc50e7deaf08b21080f86857594958ff3c7290977efad99fb","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=117;cells=A117:I117"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('462b9332-d4ee-57ef-b57c-d139b5766a98'::uuid, '8ebb6988-9b4c-5018-b943-2cdcf14651a1'::uuid, 1, '浙江适用杂草：红蓼（东方蓼）', '{"kind":"weed","item_id":"zj-weed-r119","weed_name":"红蓼（东方蓼）","canonical_name":"红蓼","scientific_name":"Polygonum orientale","family_genus":"蓼科·蓼属","companion_crops":["水稻田边","玉米","大豆","蔬菜","湿地"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","贵州","陕西","辽宁","黑龙江","台湾"],"growth_stages_text":"① 幼苗期：茎直立、叶片宽大卵形；② 旺长期：株高1～2m、茎粗壮、全株有毛；③ 开花期：穗状花序大型下垂、淡红色或白色；④ 结实期：小坚果扁圆形、黑色有光泽。","best_control_stage_text":"幼苗期至旺长初期。红蓼植株高大、竞争力强，须在苗期处理。","spray_window_text":"稻田边与旱作田早期处理；结合清除田边杂草。","identification_key_text":"植株高大（可达2m）、茎粗壮、全株密生柔毛；穗状花序大型下垂、淡红色或白色；叶片宽大卵形、托叶鞘明显。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":119,"cell_range":"A119:I119","row_sha256":"685f0a6851b149852e62e4acdf4c6562392ba2178fab36a617d671f129f70d35","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=119;cells=A119:I119"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('25fb1813-daf1-554b-a1ae-15f0fada5d61'::uuid, '67f6ac03-455b-5c1e-858d-86be2ad4fe55'::uuid, 1, '浙江适用杂草：马松子', '{"kind":"weed","item_id":"zj-weed-r120","weed_name":"马松子","canonical_name":"马松子","scientific_name":"Melochia corchorifolia","family_genus":"锦葵科·马松子属","companion_crops":["水稻","大豆","甘蔗","蔬菜","果园"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","云南","贵州","台湾"],"growth_stages_text":"① 幼苗期：叶片卵形有齿；② 旺长期：株高30～100cm、茎直立多分枝、有星状毛；③ 开花期：花小、粉红色或白色、簇生；④ 结实期：蒴果小、种子多。","best_control_stage_text":"幼苗期至旺长初期。","spray_window_text":"稻田与旱作田早期处理；果园定向处理。","identification_key_text":"全株有星状毛（手感粗糙）；叶片卵形、边缘有锯齿；花小、粉红色或白色、簇生；蒴果小、5瓣开裂。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":120,"cell_range":"A120:I120","row_sha256":"100f309c82058179bf43cb2c8dcdca7e6d82426a82b675d95bf11fac449efd4a","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=120;cells=A120:I120"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('98705db1-44ce-5a35-8b2e-5636577b4244'::uuid, '5df10a8c-dae3-5dd3-b5e1-dda7aff81eea'::uuid, 1, '浙江适用杂草：苘麻', '{"kind":"weed","item_id":"zj-weed-r121","weed_name":"苘麻","canonical_name":"苘麻","scientific_name":"Abutilon theophrasti","family_genus":"锦葵科·苘麻属","companion_crops":["玉米","大豆","棉花","花生","蔬菜","向日葵"],"distribution_note":"","distribution_provinces":["黑龙江","吉林","辽宁","河北","河南","山东","山西","陕西","甘肃","新疆","内蒙古","江苏","安徽","湖北","湖南","江西","浙江","四川","云南","福建","台湾"],"growth_stages_text":"① 幼苗期：子叶心形、下胚轴紫红；② 苗期：叶片心形、边缘有细齿、密生星状毛；③ 旺长期：株高0.5～2m、茎直立粗壮；④ 开花期：花单生叶腋、黄色、5瓣；⑤ 结实期：果实为半球形蒴果、由多数心皮轮状排列呈「轮盘状」（形似小磨盘，是识别关键）。","best_control_stage_text":"2～4叶期幼苗阶段。苘麻植株高大粗壮、根系发达，一旦封行后防除成本极高。","spray_window_text":"大豆、玉米、棉花田播后苗前封闭加苗后2～4叶期茎叶处理；须在封行前完成。","identification_key_text":"果实呈轮盘状（半球形，由多数心皮放射状排列，形似小磨盘，最典型特征）；叶片心形、边缘有细齿、两面密生星状毛；幼苗下胚轴紫红色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":121,"cell_range":"A121:I121","row_sha256":"b6908a3e07a8fd3a52c41d2293c5ded953f7834fd2f2f3c0b6e98dd4158fe221","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=121;cells=A121:I121"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('c1f34ad3-c6c1-58f2-80cd-6d7378a596e6'::uuid, '643fc943-fe48-58b4-a43d-a8786ab3c0be'::uuid, 1, '浙江适用杂草：铁苋菜（海蚌含珠）', '{"kind":"weed","item_id":"zj-weed-r123","weed_name":"铁苋菜（海蚌含珠）","canonical_name":"铁苋菜","scientific_name":"Acalypha australis","family_genus":"大戟科·铁苋菜属","companion_crops":["玉米","大豆","棉花","花生","蔬菜","果园"],"distribution_note":"全国广布","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","重庆","云南","贵州","陕西","山西","甘肃","辽宁","吉林","黑龙江","台湾"],"growth_stages_text":"① 幼苗期：叶片菱状卵形有齿；② 旺长期：株高30～80cm、茎直立多分枝；③ 开花期：花单性、雌花藏于叶状苞片内（苞片合拢如蚌壳内含珍珠，故名「海蚌含珠」）；④ 结实期：蒴果小、种子细小。","best_control_stage_text":"幼苗期至旺长初期（2～4叶期最佳）。铁苋菜在玉米、大豆田发生量大，须早期处理。","spray_window_text":"玉米、大豆、棉花田播后苗前封闭加苗后早期处理；果园定向处理。","identification_key_text":"雌花被合拢的叶状苞片包裹、形如蚌壳内含珍珠（「海蚌含珠」由此得名，是识别捷径）；叶片菱状卵形、边缘有锯齿；茎带红紫色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":123,"cell_range":"A123:I123","row_sha256":"6e2b361b076ab9da4c5984c632d34e1f91661b086600ab699928738ca943adc0","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=123;cells=A123:I123"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('415e39a9-966d-5591-80d4-cc52f5cc4b01'::uuid, '743f565b-a7cc-51f0-a16f-5151ae15661d'::uuid, 1, '浙江适用杂草：地锦（斑地锦）', '{"kind":"weed","item_id":"zj-weed-r124","weed_name":"地锦（斑地锦）","canonical_name":"地锦","scientific_name":"Euphorbia humifusa","family_genus":"大戟科·大戟属","companion_crops":["棉花","大豆","玉米","蔬菜","果园","草坪"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","陕西","辽宁","吉林","黑龙江","新疆","台湾"],"growth_stages_text":"① 幼苗期：茎匍匐、带红紫色；② 营养生长期：茎平铺地面、多分枝、形成红色草层；③ 开花期：杯状聚伞花序极小、腋生；④ 结实期：蒴果三棱状、极小。","best_control_stage_text":"幼苗期至营养生长前期。地锦平铺地面、再生力强，须在覆盖地表前处理。","spray_window_text":"棉花、大豆田苗前封闭加苗后早期处理；草坪与果园早期处理。","identification_key_text":"茎匍匐平铺地面、红紫色、折断有白色乳汁；叶片极小、对生、偏斜（叶基不对称，故称「斑地锦」）、边缘有细齿；果实极小、三棱状。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":124,"cell_range":"A124:I124","row_sha256":"8900e98b70797e83dd88bc48cd67d82d62b9a260fefabf34786ea7971b3cf6f0","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=124;cells=A124:I124"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_soybean","crop_corn"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('0b2db47e-df0e-5ef0-a2a7-b983ccc8896e'::uuid, 'f84a8f89-6fa3-5683-b2d2-e8a4b27f0a7e'::uuid, 1, '浙江适用杂草：飞扬草', '{"kind":"weed","item_id":"zj-weed-r125","weed_name":"飞扬草","canonical_name":"飞扬草","scientific_name":"Euphorbia hirta","family_genus":"大戟科·大戟属","companion_crops":["甘蔗","果园","蔬菜","非耕地","草坪"],"distribution_note":"","distribution_provinces":["福建","广东","广西","海南","云南","贵州","四川","江西","湖南","浙江","台湾"],"growth_stages_text":"① 幼苗期：茎匍匐或上升、带红紫色；② 旺长期：株高15～50cm、全株有毛、折断有白色乳汁；③ 开花期：杯状聚伞花序密集成球形腋生；④ 结实期：蒴果三棱状、有毛。","best_control_stage_text":"幼苗期至旺长初期。","spray_window_text":"甘蔗田、果园、草坪早期处理；非耕地苗期施药。","identification_key_text":"全株有黄褐色硬毛、折断流出白色乳汁；花序密集成球形簇生于叶腋（形似「飞扬」）；叶片对生、矩圆形、边缘有细齿、基部偏斜。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":125,"cell_range":"A125:I125","row_sha256":"de1a5c2739f3aabf8d94653d2d12c16cfdfda10bcac124ee6f31396c44c9cadd","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=125;cells=A125:I125"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('6a4f0fe7-2b01-5863-99a7-d37a81f4af19'::uuid, '5fac231a-8a10-5881-95d4-a662710514f6'::uuid, 1, '浙江适用杂草：蕹菜（空心菜野生型／水蕹菜）', '{"kind":"weed","item_id":"zj-weed-r126","weed_name":"蕹菜（空心菜野生型／水蕹菜）","canonical_name":"蕹菜","scientific_name":"Ipomoea aquatica 野生型","family_genus":"旋花科·番薯属","companion_crops":["水稻","湿地农田","蔬菜"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","云南","台湾"],"growth_stages_text":"① 幼苗期：茎中空、匍匐水面或湿地；② 营养生长期：茎蔓生蔓延、节上生根、茎中空（故名空心菜）；③ 开花期：花漏斗状、白色或淡紫色；④ 结实期：蒴果、种子有毛。","best_control_stage_text":"幼苗期至蔓延初期。野生蕹菜以无性繁殖为主，须在连片蔓延前处理。","spray_window_text":"稻田与湿地早期处理；结合清沟与排水。","identification_key_text":"茎中空（折断可见明显孔道，是识别捷径）；茎蔓生、节上生根；花漏斗状、白色或淡紫色；叶片与栽培空心菜相同但较窄小。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":126,"cell_range":"A126:I126","row_sha256":"195c79806db24d846265cf02bdf10a8b867c0aeb0fb2a7375560f350854c129b","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=126;cells=A126:I126"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('feed7e87-fb8e-560b-a335-00395a24f085'::uuid, 'c6c089f2-d28e-56e2-8729-7cbe27b79ac6'::uuid, 1, '浙江适用杂草：田菁（野生型）', '{"kind":"weed","item_id":"zj-weed-r127","weed_name":"田菁（野生型）","canonical_name":"田菁","scientific_name":"Sesbania cannabina 野生型","family_genus":"豆科·田菁属","companion_crops":["水稻田边","棉花","果园","非耕地"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","福建","广东","广西","海南","四川","云南","台湾"],"growth_stages_text":"① 幼苗期：羽状复叶、茎带红；② 旺长期：株高1～3m、茎粗壮木质化；③ 开花期：花黄色、蝶形；④ 结实期：荚果细长、种子多。","best_control_stage_text":"幼苗期至旺长初期。","spray_window_text":"田边与非耕地早期处理；结合清除田埂。","identification_key_text":"羽状复叶、小叶多数；花黄色蝶形；荚果细长；野生型植株较栽培型细弱、分枝多、茎带红色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":127,"cell_range":"A127:I127","row_sha256":"443b9d45cab098b283bd53f389e2793afeeeddec14e7f7d50979a6fcf5ba5079","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=127;cells=A127:I127"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('1dd9690e-c5fa-548f-a9cc-535231e52f65'::uuid, '0b05bf54-bdfc-5641-bf29-d6b6157aca54'::uuid, 1, '浙江适用杂草：大巢菜（救荒野豌豆）', '{"kind":"weed","item_id":"zj-weed-r128","weed_name":"大巢菜（救荒野豌豆）","canonical_name":"大巢菜","scientific_name":"Vicia sativa","family_genus":"豆科·野豌豆属","companion_crops":["小麦","油菜","果园","绿肥田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","河南","山东","河北","陕西","山西","甘肃","四川","云南","贵州","福建","广西","辽宁","黑龙江"],"growth_stages_text":"① 幼苗期：羽状复叶、顶端有卷须；② 营养生长期：茎蔓生攀援、缠绕作物；③ 开花期：花蝶形、紫红色或蓝紫色、单生或双生叶腋；④ 结实期：荚果扁、种子球形褐色。","best_control_stage_text":"幼苗期至攀援初期。大巢菜缠绕作物、与小麦争肥争光严重，须在缠绕前处理。","spray_window_text":"麦田冬前或返青期茎叶处理；油菜田注意选药。","identification_key_text":"羽状复叶、小叶先端有卷须（可攀援，是识别关键）；花蝶形、紫红色或蓝紫色、单生或双生叶腋；荚果扁、成熟后开裂。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":128,"cell_range":"A128:I128","row_sha256":"b97051b5a8096278ff18af4546f542fa9977633b403cd109576ca6f60b9d63d3","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=128;cells=A128:I128"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('8363aea2-9a3c-50af-8cdd-e51bbad4cbef'::uuid, '3f1addd8-f57c-525e-997c-daebed218039'::uuid, 1, '浙江适用杂草：小巢菜（硬毛果野豌豆）', '{"kind":"weed","item_id":"zj-weed-r129","weed_name":"小巢菜（硬毛果野豌豆）","canonical_name":"小巢菜","scientific_name":"Vicia hirsuta","family_genus":"豆科·野豌豆属","companion_crops":["小麦","油菜","绿肥田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","河南","山东","陕西","四川","云南","贵州","福建","广西"],"growth_stages_text":"① 幼苗期：羽状复叶、小叶细小、有卷须；② 营养生长期：茎蔓生攀援、缠绕作物；③ 开花期：花极小、白色或淡紫色、2～5朵聚生；④ 结实期：荚果扁、密生硬毛、内含种子2粒。","best_control_stage_text":"幼苗期至攀援初期。","spray_window_text":"麦田冬前或返青期处理。","identification_key_text":"荚果密生硬毛（「硬毛果」得名，是识别关键）；小叶细小、卷须明显；花极小、白色或淡紫色；植株比大巢菜纤细。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":129,"cell_range":"A129:I129","row_sha256":"c5cf5410aed286f58fea47d9f14db8fd9382cd0ca74a4fb7219c72929ffbb561","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=129;cells=A129:I129"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('b3056629-a078-574b-8d66-06d5362f8f8d'::uuid, '251890e5-6f1c-51b9-a470-46c80c7d8b8a'::uuid, 1, '浙江适用杂草：鸡眼草', '{"kind":"weed","item_id":"zj-weed-r132","weed_name":"鸡眼草","canonical_name":"鸡眼草","scientific_name":"Kummerowia striata","family_genus":"豆科·鸡眼草属","companion_crops":["玉米","大豆","果园","茶园","草坪","非耕地"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","贵州","陕西","辽宁","吉林","黑龙江","台湾"],"growth_stages_text":"① 幼苗期：茎纤细匍匐、三出复叶；② 营养生长期：茎平卧蔓延、多分枝、形成草层；③ 开花期：花小、粉红色、1～3朵簇生叶腋；④ 结实期：荚果小、顶端有喙、形如鸡眼（故名）。","best_control_stage_text":"幼苗期至蔓延前期。","spray_window_text":"果园、茶园与草坪早期处理；农田结合封闭处理。","identification_key_text":"三出复叶、小叶倒卵形、主脉明显偏于一侧；荚果小而扁、顶端具弯曲尖喙、形如鸡眼（识别捷径）；茎匍匐纤细。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":132,"cell_range":"A132:I132","row_sha256":"a7b9128328612792651be1f99da88a748ddf4f8559842130d755cbf2965c8234","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=132;cells=A132:I132"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('e8933ba2-1b34-5848-8151-d1049a3611ea'::uuid, '9887e81c-e346-50ae-9e99-d5c196f71d14'::uuid, 1, '浙江适用杂草：决明（野生型）', '{"kind":"weed","item_id":"zj-weed-r133","weed_name":"决明（野生型）","canonical_name":"决明","scientific_name":"Senna tora 野生型","family_genus":"豆科·决明属","companion_crops":["甘蔗","果园","非耕地","路边"],"distribution_note":"","distribution_provinces":["福建","广东","广西","海南","云南","贵州","四川","江西","湖南","浙江","台湾"],"growth_stages_text":"① 幼苗期：羽状复叶、小叶对生；② 旺长期：株高0.5～2m、茎直立；③ 开花期：花黄色、5瓣；④ 结实期：荚果细长四棱状、种子多。","best_control_stage_text":"幼苗期至旺长初期。","spray_window_text":"甘蔗田与果园早期处理；非耕地苗期施药。","identification_key_text":"羽状复叶、小叶对生；花黄色5瓣；荚果细长、具明显四棱（是识别关键）。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":133,"cell_range":"A133:I133","row_sha256":"4735e49d34579925310662ddbccc1948ac25871d9fa4f5d7e582fc7345fb0f47","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=133;cells=A133:I133"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('f54f11da-3982-598e-9e0f-baeb05e89bd0'::uuid, 'f498d7f5-97e1-54e4-a367-2613ebd9d231'::uuid, 1, '浙江适用杂草：鸭舌草', '{"kind":"weed","item_id":"zj-weed-r135","weed_name":"鸭舌草","canonical_name":"鸭舌草","scientific_name":"Monochoria vaginalis","family_genus":"雨久花科·雨久花属","companion_crops":["水稻","湿地农田"],"distribution_note":"全国各稻区","distribution_provinces":["黑龙江","吉林","辽宁","河北","河南","山东","江苏","浙江","安徽","江西","湖北","湖南","广东","广西","福建","海南","四川","重庆","贵州","云南","陕西","台湾"],"growth_stages_text":"① 幼苗期：叶片卵形或心形、浮水或挺水，叶柄短；② 旺长期：株高10～30cm（比雨久花矮小）；③ 开花期：花蓝色略带紫、总状花序、3～6朵；④ 结实期：蒴果、种子极多。","best_control_stage_text":"幼苗期至旺长初期（株高10cm以内）。鸭舌草是稻田分布最广的阔叶杂草之一，须在移栽后早期处理。","spray_window_text":"稻田移栽后5～10天土壤封闭或苗后早期茎粗处理（苄嘧磺隆、吡嘧磺隆等）。","identification_key_text":"叶片形状多变（幼苗期卵形、成株心形）、基部心形或圆形、有弧形脉；花蓝色略带紫、较小；植株较雨久花矮小、叶柄较短。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":135,"cell_range":"A135:I135","row_sha256":"ea2995158a3c564e6a3597b6475cd2ed5d8c8ef9cb2c218e23b3cc7afef2a4d3","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=135;cells=A135:I135"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('92e55d0c-9573-5626-b1ab-167cfb83efa4'::uuid, 'd30d394f-8c42-5974-9c17-fe31c91d5c36'::uuid, 1, '浙江适用杂草：水竹叶', '{"kind":"weed","item_id":"zj-weed-r136","weed_name":"水竹叶","canonical_name":"水竹叶","scientific_name":"Murdannia triquetra","family_genus":"鸭跖草科·水竹叶属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","云南","河南","台湾"],"growth_stages_text":"① 幼苗期：茎匍匐、叶片狭长似竹叶；② 营养生长期：茎匍匐蔓延、节上生根；③ 开花期：花蓝紫色、单生或聚生；④ 结实期：蒴果、种子有网纹。","best_control_stage_text":"幼苗期至蔓延前期。水竹叶匍匐茎节上生根、再生力强，须在蔓延前处理。","spray_window_text":"稻田移栽后早期处理；结合中耕与排水。","identification_key_text":"叶片狭长披针形、形似竹叶（故名）；茎匍匐、节上生根；花蓝紫色、花瓣3枚；常见于稻田与湿地。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":136,"cell_range":"A136:I136","row_sha256":"56ec378e7a0fcf954cb7dc41820c69cfb58fa8887f88ff0a4f46494ca10f11f9","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=136;cells=A136:I136"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('2dc05394-74d4-511b-9c4a-a880fdb04c90'::uuid, '77d77762-2152-5512-a082-7c7c63dc81b5'::uuid, 1, '浙江适用杂草：节节菜', '{"kind":"weed","item_id":"zj-weed-r137","weed_name":"节节菜","canonical_name":"节节菜","scientific_name":"Rotala indica","family_genus":"千屈菜科·节节菜属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","云南","河南","台湾"],"growth_stages_text":"① 幼苗期：茎细弱、叶片对生；② 营养生长期：茎匍匐或直立、多分枝、节明显；③ 开花期：花极小、淡红色、单生叶腋；④ 结实期：蒴果小、种子极小极多。","best_control_stage_text":"幼苗期至营养生长前期。节节菜在稻田密度极高，须在早期封闭处理时一并防除。","spray_window_text":"稻田移栽后5～10天土壤封闭处理或早期茎叶处理。","identification_key_text":"茎细弱、多分枝、节明显（故名「节节菜」）；叶片对生、倒卵形至椭圆形；花极小、淡红色、单生叶腋；常形成密集的红色草层。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":137,"cell_range":"A137:I137","row_sha256":"a7fc148f38f8a2dd2a1139944c03e53c0172ccd4a9de81aa69b24ad79fba5cc4","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=137;cells=A137:I137"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('7e15055c-ebae-5fc6-b70a-5bd08f8c4f5a'::uuid, 'e004ed05-d3a3-5af4-bb05-c5b33d6d9afe'::uuid, 1, '浙江适用杂草：多花水苋（水苋菜）', '{"kind":"weed","item_id":"zj-weed-r138","weed_name":"多花水苋（水苋菜）","canonical_name":"多花水苋","scientific_name":"Ammannia multiflora","family_genus":"千屈菜科·水苋菜属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","云南","河南","台湾"],"growth_stages_text":"① 幼苗期：茎四棱、叶片对生；② 营养生长期：株高10～40cm、茎四棱、多分枝；③ 开花期：花极小、淡紫色、密生于叶腋；④ 结实期：蒴果球形、种子极小极多。","best_control_stage_text":"幼苗期至营养生长前期。","spray_window_text":"稻田移栽后早期处理。","identification_key_text":"茎四棱形、常带红紫色；叶片对生、狭披针形、基部呈耳状抱茎；花极小、淡紫色、密生叶腋。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":138,"cell_range":"A138:I138","row_sha256":"7d78f417836cf76707f8355de7649e746a8f1ec91249f43c49169d0607ee21c2","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=138;cells=A138:I138"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('e436d0ee-c2e1-5d3b-b848-852cc6699597'::uuid, '0451cf0d-f753-52ae-a633-c774fdf0b12b'::uuid, 1, '浙江适用杂草：矮慈姑（瓜皮草）', '{"kind":"weed","item_id":"zj-weed-r139","weed_name":"矮慈姑（瓜皮草）","canonical_name":"矮慈姑","scientific_name":"Sagittaria pygmaea","family_genus":"泽泻科·慈姑属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","云南","河南","山东","台湾"],"growth_stages_text":"① 球茎期：地下具小球茎、是主要繁殖器官；② 幼苗期：叶片线形或带状、沉水或挺水；③ 开花期：花白色、3瓣、轮生于花序轴上；④ 越冬期：小球茎在土中越冬。","best_control_stage_text":"幼苗期（叶片带状、株高10cm以内）。矮慈姑以球茎繁殖、再生力强，须在球茎大量形成前处理。","spray_window_text":"稻田移栽后5～15天早期处理；结合秋耕破坏球茎。","identification_key_text":"叶片线形或带状（与野慈姑的箭头形叶明显不同）；地下具小球茎；花白色3瓣；植株矮小（故名「矮」慈姑）。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":139,"cell_range":"A139:I139","row_sha256":"2364124858669a31a6bdfa96383a56733b52f896550c7f94b049dd062801731c","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=139;cells=A139:I139"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('3fe1b0b9-d3ea-5596-9303-1f0022d74d7f'::uuid, 'e5008800-236e-571a-9a83-93b5eb9199e3'::uuid, 1, '浙江适用杂草：野慈姑（慈姑）', '{"kind":"weed","item_id":"zj-weed-r140","weed_name":"野慈姑（慈姑）","canonical_name":"野慈姑","scientific_name":"Sagittaria trifolia","family_genus":"泽泻科·慈姑属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["黑龙江","吉林","辽宁","河北","河南","山东","江苏","浙江","安徽","江西","湖北","湖南","广东","广西","福建","四川","云南","陕西","新疆","台湾"],"growth_stages_text":"① 球茎期：地下具球茎；② 幼苗期：叶片箭头形（重要识别特征）；③ 旺长期：株高30～100cm、叶柄长、叶片箭形；④ 开花期：花白色、3瓣、轮生；⑤ 越冬期：球茎越冬。","best_control_stage_text":"幼苗期至旺长初期（株高20cm以内）。野慈姑球茎繁殖力强，须在早期处理并结合秋耕。","spray_window_text":"稻田移栽后早期处理；结合秋耕破坏球茎；水旱轮作可显著降低基数。","identification_key_text":"叶片箭头形（基部有两个向下的裂片，形如箭头，是与矮慈姑最明显的区别）；花白色3瓣轮生；地下具球茎。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":140,"cell_range":"A140:I140","row_sha256":"3d5e9d2ced173e2ea2117e1bd99589a292f25530b4069f43706c9f2d03556abc","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=140;cells=A140:I140"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('f8440e1a-957b-56c8-87b5-fe445cb53e14'::uuid, 'd9128c74-a97e-52ac-b098-a6f21005728b'::uuid, 1, '浙江适用杂草：眼子菜（竹叶眼子菜）', '{"kind":"weed","item_id":"zj-weed-r141","weed_name":"眼子菜（竹叶眼子菜）","canonical_name":"眼子菜","scientific_name":"Potamogeton distinctus","family_genus":"眼子菜科·眼子菜属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["黑龙江","吉林","辽宁","河北","山东","江苏","浙江","安徽","江西","湖北","湖南","四川","云南","内蒙古","新疆","台湾"],"growth_stages_text":"① 沉水/浮水期：茎细长、叶片浮水或沉水、有长叶柄；② 蔓延期：以根茎和匍匐茎在泥中蔓延、形成连片群落；③ 开花期：穗状花序伸出水面、花小绿色；④ 越冬期：根茎和冬芽在泥中越冬。","best_control_stage_text":"浮叶形成初期至蔓延前期。眼子菜一旦连片覆盖水面，会造成水稻坐蔸、水温降低，防除极困难。","spray_window_text":"稻田在浮叶初期（移栽后10～20天）施用专用药剂（如吡嘧磺隆、五氟磺草胺）；结合排水晒田、秋耕破坏根茎。","identification_key_text":"叶片浮于水面、长椭圆形、有长叶柄、基部有膜质托叶；穗状花序伸出水面；水下有细长根茎与匍匐茎在泥中蔓延成网。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":141,"cell_range":"A141:I141","row_sha256":"38070c324a767b5e0e2cd67794ecefaa7588225892ffc136edb586333c410ffc","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=141;cells=A141:I141"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('17469a91-c0d2-5067-9c22-3908e054eb11'::uuid, '46176923-cae0-51bf-a7ed-e7ceb20c13ee'::uuid, 1, '浙江适用杂草：苹（四叶苹）', '{"kind":"weed","item_id":"zj-weed-r142","weed_name":"苹（四叶苹）","canonical_name":"苹","scientific_name":"Marsilea quadrifolia","family_genus":"苹科·苹属","companion_crops":["水稻","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","云南","河南","山东","台湾"],"growth_stages_text":"① 幼苗期：叶片为「四叶草」状（4枚小叶呈十字形排列）；② 蔓延期：以细长根茎在水下泥中蔓延、形成连片；③ 孢子果期：叶柄基部形成孢子果；④ 越冬期：根茎越冬。","best_control_stage_text":"幼苗期至蔓延前期。","spray_window_text":"稻田早期处理；结合排水晒田与秋耕。","identification_key_text":"叶片呈「四叶草」状（4枚小叶十字形排列于叶柄顶端，极易识别）；根茎细长在泥中蔓延；常见于稻田与湿地。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":142,"cell_range":"A142:I142","row_sha256":"3200fa205ddbc3d3e88ba98ef993c818857f5d74ed485c7f2fcb5cb3ff5ac3c5","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=142;cells=A142:I142"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('e04391eb-b63d-5f2f-a8da-41aaf37e6d95'::uuid, 'cc761df2-a51f-5e5f-87ff-931ad09e773a'::uuid, 1, '浙江适用杂草：水绵（青苔）', '{"kind":"weed","item_id":"zj-weed-r143","weed_name":"水绵（青苔）","canonical_name":"水绵","scientific_name":"Spirogyra spp.","family_genus":"双星藻科·水绵属","companion_crops":["水稻（稻田水面）"],"distribution_note":"","distribution_provinces":["黑龙江","吉林","辽宁","河北","山东","江苏","浙江","安徽","江西","湖北","湖南","四川","云南","新疆","内蒙古"],"growth_stages_text":"① 萌发期：水温低时（15℃左右）在田水中萌发成丝状体；② 旺盛期：丝状体大量繁殖、水面形成绿色絮状或膜状覆盖层、缠绕稻苗；③ 衰退期：水温升高或营养耗尽后下沉形成「水绵层」。","best_control_stage_text":"萌发初期至絮状体形成前。水绵一旦大量繁殖会缠绕稻苗、降低水温泥温、影响水稻分蘖，须在早期处理。","spray_window_text":"稻田在移栽后早期（水绵初现时）施用硫酸铜、石膏或专用除藻药剂；结合排水晒田、增施磷钾肥抑制。","identification_key_text":"为丝状绿藻（非高等植物）：用手捞起可见绿色丝状体、手感滑腻、表面有黏滑感；显微镜下可见螺旋状叶绿体（Spirogyra）；水面呈绿色絮状或膜状覆盖。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":143,"cell_range":"A143:I143","row_sha256":"0e6515b5b5c456b254c74270eb5977c757ace9c6facc5a03b27f03a4eefe0b25","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=143;cells=A143:I143"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('80bdd338-3e81-52f9-94d1-f80051651fbf'::uuid, '0c79703b-d37e-5c6a-ba01-2a808931e688'::uuid, 1, '浙江适用杂草：南方菟丝子（田菟丝子）', '{"kind":"weed","item_id":"zj-weed-r145","weed_name":"南方菟丝子（田菟丝子）","canonical_name":"南方菟丝子","scientific_name":"Cuscuta australis","family_genus":"旋花科·菟丝子属（寄生植物）","companion_crops":["大豆","苜蓿","蔬菜","果树","甘蔗"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","云南","贵州","台湾"],"growth_stages_text":"① 种子萌发期：同上，须快速找到寄主；② 缠绕寄生期：茎丝状、黄色，吸器刺入寄主；③ 开花期：花极小、白色、密集成团；④ 结实期：蒴果、种子极小、寿命长。","best_control_stage_text":"缠绕寄生初期，及时摘除并销毁。","spray_window_text":"人工摘除销毁；清选种子；与非寄主作物轮作；深翻。","identification_key_text":"与菟丝子极相似，区别在于南方菟丝子花更小更密、柱头形态不同；同为黄色丝状缠绕茎、无叶片、以吸器寄生。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":145,"cell_range":"A145:I145","row_sha256":"aff8e3ccc578da0cda1cb26209d54d9e654d0e473ec3a339a35bbcaedc624d08","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=145;cells=A145:I145"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('f87ac4cb-b033-58cd-8b71-9a7e04fcf02f'::uuid, '7e983e5c-39a9-54d6-b686-6508d34c023c'::uuid, 1, '浙江适用杂草：野菰', '{"kind":"weed","item_id":"zj-weed-r149","weed_name":"野菰","canonical_name":"野菰","scientific_name":"Aeginetia indica","family_genus":"列当科·野菰属（寄生植物）","companion_crops":["甘蔗","玉米","芒","禾本科杂草根部"],"distribution_note":"","distribution_provinces":["浙江","福建","广东","广西","江西","湖南","四川","云南","贵州","台湾"],"growth_stages_text":"① 地下寄生期：寄生于禾本科植物根部；② 出土期：花茎从土中抽出、肉质；③ 开花期：花大、单生、淡紫红色、花冠呈管状二唇形、形如小喇叭；④ 结实期：蒴果、种子多。","best_control_stage_text":"出土后开花前拔除销毁。","spray_window_text":"拔除销毁；与非寄主作物轮作；结合清除田间禾本科宿根杂草（其寄主）。","identification_key_text":"花大而醒目、淡紫红色、花冠管状二唇形、单生于肉质花茎顶端（形似小喇叭，极易识别）；全株无叶绿素；寄生于甘蔗、芒等禾本科植物根部。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":149,"cell_range":"A149:I149","row_sha256":"245b1f356236f68b5cadc5e8bde2d1dff86d424b9e552e1abd418fdcd088d2d2","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=149;cells=A149:I149"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('072feaa2-d6b4-59c7-94e4-9a2b4c840177'::uuid, 'cf916c5c-8c6b-5433-8e4b-a567cb6da0a2'::uuid, 1, '浙江适用杂草：无根藤', '{"kind":"weed","item_id":"zj-weed-r150","weed_name":"无根藤","canonical_name":"无根藤","scientific_name":"Cassytha filiformis","family_genus":"樟科·无根藤属（寄生植物）","companion_crops":["柑橘","茶树","果树","林木","灌木"],"distribution_note":"","distribution_provinces":["广东","广西","福建","海南","云南","江西","湖南","浙江","台湾"],"growth_stages_text":"① 缠绕寄生期：茎丝状、黄绿色、无叶片、以吸盘附着寄主吸取养分；② 蔓延期：迅速缠绕覆盖寄主树冠；③ 开花期：花极小、白色、穗状；④ 结实期：果实小、种子多。","best_control_stage_text":"缠绕初期及时剪除并销毁，同时剪除被严重缠绕的枝条。","spray_window_text":"人工剪除缠绕茎并带出园外销毁；加强树体管理、增强树势；定期巡查。","identification_key_text":"茎丝状、黄绿色、无叶片无根、以吸盘缠绕附着（与菟丝子相似但无根藤茎偏黄绿、寄主多为木本）；花极小、白色穗状。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":150,"cell_range":"A150:I150","row_sha256":"491b4348c93cdbb1fa6a9274e7c51c03197febb1439a969f9eb48172784a34f6","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=150;cells=A150:I150"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('2632d097-dddf-519d-bcaf-e6bad44be895'::uuid, '526dfa3e-0a45-5262-a102-92b17c2226eb'::uuid, 1, '浙江适用杂草：节节草（土木贼）', '{"kind":"weed","item_id":"zj-weed-r152","weed_name":"节节草（土木贼）","canonical_name":"节节草","scientific_name":"Equisetum ramosissimum","family_genus":"木贼科·木贼属（蕨类）","companion_crops":["棉花","大豆","玉米","果园","非耕地"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","陕西","新疆","台湾"],"growth_stages_text":"① 根茎蔓延期：以地下根茎横向蔓延；② 营养茎期：茎直立、灰绿色、粗糙、节上有分枝、株高30～100cm；③ 孢子期：茎顶生孢子囊穗（穗较钝）；④ 越冬期：根茎越冬。","best_control_stage_text":"营养茎萌发初期至株高20cm前，配合深翻。","spray_window_text":"果园与非耕地营养茎初期施药；农田结合深翻；连续多年防治。","identification_key_text":"茎灰绿色、粗糙、质硬、节上有分枝（与问荆不同：节节草茎不分两型、终年绿色、分枝较多）；节间有纵棱、手感粗糙；孢子囊穗钝头。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":152,"cell_range":"A152:I152","row_sha256":"1f5fe173b4a07e6815d770fa6dcf307ad7b988b97e4440765bc30ba7c935b5a9","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=152;cells=A152:I152"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_soybean","crop_corn"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('cae2d554-4098-58e3-949a-a0a580602ae3'::uuid, '7220780c-d4b7-5b45-8ec4-1a9b212861ba'::uuid, 1, '浙江适用杂草：满江红（红萍）', '{"kind":"weed","item_id":"zj-weed-r153","weed_name":"满江红（红萍）","canonical_name":"满江红","scientific_name":"Azolla imbricata","family_genus":"满江红科·满江红属（水生蕨类）","companion_crops":["水稻（稻田水面）","湿地"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","四川","云南","河南","台湾"],"growth_stages_text":"① 繁殖期：以断裂繁殖迅速覆盖水面，秋后转红褐色；② 覆盖期：形成厚密覆盖层、遮挡阳光、降低水温；③ 越冬期：以孢子果在泥中越冬。","best_control_stage_text":"覆盖初期（尚未连片时）。满江红既是绿肥也是杂草，须根据用途决定是否防除。","spray_window_text":"作为绿肥可保留利用；若影响水稻则排水晒田、施用除藻药剂或人工打捞。","identification_key_text":"漂浮水面、植株细小、叶片覆瓦状排列成两行、呈三角形（秋季转红褐色，故名「满江红」「红萍」）；根细长悬垂水中。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":153,"cell_range":"A153:I153","row_sha256":"387a7298eca23504e7d32d6af17dd2fd24d1d155839ccf9dd2c970221ad7da0a","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=153;cells=A153:I153"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('4336d58d-6335-5912-901e-4cb01962f881'::uuid, '9dc57a9a-9791-5772-9037-77db73c5f911'::uuid, 1, '浙江适用杂草：空心莲子草（水花生、喜旱莲子草）', '{"kind":"weed","item_id":"zj-weed-r154","weed_name":"空心莲子草（水花生、喜旱莲子草）","canonical_name":"空心莲子草","scientific_name":"Alternanthera philoxeroides","family_genus":"苋科·莲子草属","companion_crops":["水稻","蔬菜","果园","鱼塘","沟渠","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","重庆","云南","贵州","河南","山东","陕西","上海","台湾"],"growth_stages_text":"① 匍匐/漂浮期：水生型茎漂浮水面、陆生型茎匍匐地面，节上生根；② 蔓延期：以匍匐茎和根茎快速无性繁殖、断节即可成新株，形成连片厚密群落；③ 开花期：花小、白色、密集成球状头状花序；④ 越冬期：根茎在水中或土中越冬。","best_control_stage_text":"蔓延初期（尚未连片时），须连续多次处理并清除残体。空心莲子草是首批列入《中国外来入侵物种名单》的恶性杂草，断节再生力极强，单次施药必然复发。","spray_window_text":"水稻田与沟渠在蔓延初期施用灭生性药剂或专用除草剂，间隔30～45天重复；人工打捞须将残体带出田外晾干销毁（严禁随意丢弃，否则断节再生）；长期治理结合水旱轮作与深翻。","identification_key_text":"水生型茎漂浮水面、中空；陆生型茎匍匐地面、节上生根；叶片对生、长椭圆形、全缘、有光泽；花小、白色、密集成球状头状花序（形似小绒球）；茎折断后每一节均可再生为新株。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":154,"cell_range":"A154:I154","row_sha256":"ee0fef3798376bff36b91baaeeafadb44c5a32988f862fdd454004e947671351","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=154;cells=A154:I154"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '["species_alligatorweed"]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('34cfaba3-a048-5c91-900c-89bf33535e5f'::uuid, '24f4dd98-20c2-5cf5-8d0c-49ceae097c4f'::uuid, 1, '浙江适用杂草：水葫芦（凤眼莲）', '{"kind":"weed","item_id":"zj-weed-r155","weed_name":"水葫芦（凤眼莲）","canonical_name":"水葫芦","scientific_name":"Eichhornia crassipes","family_genus":"雨久花科·凤眼莲属","companion_crops":["水稻","沟渠","池塘","湿地农田"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","重庆","云南","贵州","河南","山东","台湾"],"growth_stages_text":"① 漂浮期：以匍匐茎（走茎）连接成丛漂浮水面；② 爆发期：繁殖极快（无性繁殖为主）、短期内覆盖水面、造成水体缺氧；③ 开花期：花蓝紫色、花被片中央有黄色斑块（形如凤眼，故名）；④ 越冬期：在暖地可终年生长，冷地以种子或沉水植株越冬。","best_control_stage_text":"蔓延初期（尚未覆盖水面时）人工打捞清除。水葫芦繁殖速度极快（在适宜条件下数周即可覆盖水面），一旦成灾治理成本极高。","spray_window_text":"人工或机械打捞（须从水面清除并带出销毁）；生物防治（释放水葫芦象甲）；严禁向沟渠池塘随意放养；长期治理结合水质管理。","identification_key_text":"植株漂浮水面、叶柄中部膨大呈葫芦状气囊（「水葫芦」得名，是最直观特征）；叶片圆形至心形、光滑；花蓝紫色、花被片中央有黄色斑块形如凤眼（「凤眼莲」得名）。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":155,"cell_range":"A155:I155","row_sha256":"b20cb1639a4eed757c7442a5053f64e507f4007c7047ae2ce3c186143afea987","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=155;cells=A155:I155"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('2814a4dc-af64-5c79-9fb2-225f65aaae7d'::uuid, '4355efe9-e641-5c62-9733-80840931b9fa'::uuid, 1, '浙江适用杂草：假高粱（石茅）', '{"kind":"weed","item_id":"zj-weed-r160","weed_name":"假高粱（石茅）","canonical_name":"假高粱","scientific_name":"Sorghum halepense","family_genus":"禾本科·高粱属","companion_crops":["玉米","大豆","棉花","甘蔗","果园","非耕地"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","福建","广东","广西","四川","云南","贵州","山东","河南","陕西","台湾"],"growth_stages_text":"① 根茎期：地下具粗壮根状茎、蔓延极广；② 幼苗期：形态与高粱、玉米幼苗相似；③ 抽穗期：圆锥花序大型、紫红色、株高可达2m以上；④ 结实期：种子随熟落粒，且根茎断节可萌发。","best_control_stage_text":"幼苗期至根茎蔓延前期。假高粱被列为检疫性杂草，既难防除又是高粱属作物的病虫害中间寄主。","spray_window_text":"严格检疫（防止随种子调运扩散）；幼苗期施药；结合深翻清除根状茎；连续多年防治。","identification_key_text":"地下具粗壮白色根状茎（横走蔓延）；圆锥花序大型、紫红色、分枝开展；幼苗与高粱、玉米幼苗极其相似（须在抽穗期确认）。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":160,"cell_range":"A160:I160","row_sha256":"f153b49efd6846ae17d3358722d5b972583be20e84fb21fbef5469d585f1dd6a","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=160;cells=A160:I160"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('f2a98238-87da-5370-a81f-df6c319401d0'::uuid, 'c6eaf7e1-e8e0-5a9d-9e2b-0d6547446ee5'::uuid, 1, '浙江适用杂草：加拿大一枝黄花', '{"kind":"weed","item_id":"zj-weed-r162","weed_name":"加拿大一枝黄花","canonical_name":"加拿大一枝黄花","scientific_name":"Solidago canadensis","family_genus":"菊科·一枝黄花属","companion_crops":["果园","茶园","非耕地","路边","荒地","农田边"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","上海","湖北","湖南","江西","福建","广东","广西","四川","重庆","云南","贵州","河南","山东","陕西","辽宁","台湾"],"growth_stages_text":"① 根茎蔓延期：以地下根茎横向蔓延（主要繁殖方式）、断根可萌发；② 旺长期：株高1～2.5m、茎直立；③ 开花期：头状花序极小、黄色、密集成大型圆锥状（形如一枝黄色「花棒」）；④ 结实期：种子带冠毛、随风远距离传播、单株可结籽数万粒。","best_control_stage_text":"幼苗期至根茎蔓延前期，且必须连根挖除。加拿大一枝黄花一旦结实，种子随风扩散，治理将扩展至周边大范围区域。","spray_window_text":"春季幼苗期连根挖除（须挖净根茎）或施药；秋季开花前必须清除全部花枝并销毁；连续3～5年监测治理；荒地、路边同步治理。","identification_key_text":"植株高大（1～2.5m）、茎直立；头状花序极小、黄色、密集排列于分枝一侧形成大型圆锥花序（远看如一根黄色「花棒」）；地下根茎发达、断根可再生。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":162,"cell_range":"A162:I162","row_sha256":"741fdedf5e8ca50552919a44ab81fd3af5717b391b00c080e511457a9ed6eff4","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=162;cells=A162:I162"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('d9189760-6c9a-5326-aa5d-72e1437fb940'::uuid, '600ea5f6-f024-53b6-b084-7debcda54bdd'::uuid, 1, '浙江适用杂草：大薸（水白菜）', '{"kind":"weed","item_id":"zj-weed-r163","weed_name":"大薸（水白菜）","canonical_name":"大薸","scientific_name":"Pistia stratiotes","family_genus":"天南星科·大薸属","companion_crops":["水稻","沟渠","池塘","湿地"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","江西","湖北","湖南","福建","广东","广西","海南","四川","云南","贵州","台湾"],"growth_stages_text":"① 漂浮期：植株漂浮水面、以匍匐茎连接成丛；② 爆发期：繁殖极快、覆盖水面造成缺氧；③ 开花期：花极小、不明显、藏于叶丛中央；④ 越冬期：暖地终年生长，冷地以沉水植株越冬。","best_control_stage_text":"蔓延初期人工打捞清除。","spray_window_text":"人工或机械打捞（带出销毁）；严禁向水体随意放养；结合水质管理。","identification_key_text":"植株漂浮水面、叶片簇生成莲座状、叶片倒卵形或扇形、表面密生白色绒毛、有明显的平行脉（形似白菜，故名「水白菜」）；无茎、以匍匐茎连接。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":163,"cell_range":"A163:I163","row_sha256":"ab9468a02f86b4458c6fc70c486839246b3a7b384f0db59e6a91dfd430619462","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=163;cells=A163:I163"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('821884c1-88ce-5fd3-ab45-df1376a47f1f'::uuid, '20a77dae-9642-56b1-92b3-71a7c840a789'::uuid, 1, '浙江适用杂草：葎草（拉拉秧）', '{"kind":"weed","item_id":"zj-weed-r165","weed_name":"葎草（拉拉秧）","canonical_name":"葎草","scientific_name":"Humulus scandens","family_genus":"大麻科（原桑科）·葎草属","companion_crops":["玉米","大豆","棉花","果园","非耕地","路边"],"distribution_note":"","distribution_provinces":["河北","河南","山东","山西","陕西","甘肃","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","辽宁","吉林","黑龙江","内蒙古","北京","天津","台湾"],"growth_stages_text":"① 幼苗期：茎蔓生、叶片掌状分裂；② 蔓生期：茎蔓生攀援、密生倒刺、缠绕作物形成厚密覆盖层；③ 开花期：花单性、雌花呈球状穗状花序、黄绿色；④ 结实期：瘦果藏于球状花序内、种子多。","best_control_stage_text":"幼苗期至蔓生初期（尚未形成覆盖层时）。葎草密生倒刺、缠绕力极强，一旦形成覆盖层会压倒作物并严重妨碍收割，必须在早期处理。","spray_window_text":"玉米、大豆田苗前封闭加苗后早期处理；果园与非耕地苗期施药；须在缠绕前完成；作业时戴手套（倒刺易划伤）。","identification_key_text":"茎蔓生攀援、茎和叶柄上密生倒刺（手感扎手、易划伤皮肤）；叶片掌状深裂（5～7裂）；雌花序呈球状穗状、黄绿色、形似小松球；全株粗糙。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":165,"cell_range":"A165:I165","row_sha256":"f5ce48aa0f4902f26bcadf285bd46efb89530be5c80ef861dc7775ab11a58469","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=165;cells=A165:I165"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('fda73a25-acef-5643-b168-8d16c65c56c5'::uuid, '5c259230-39cf-5715-a10a-134679271919'::uuid, 1, '浙江适用杂草：南苜蓿（黄花苜蓿）', '{"kind":"weed","item_id":"zj-weed-r166","weed_name":"南苜蓿（黄花苜蓿）","canonical_name":"南苜蓿","scientific_name":"Medicago hispida","family_genus":"豆科·苜蓿属","companion_crops":["小麦","油菜","果园","绿肥田","草坪"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","河南","山东","四川","云南","贵州","福建","广西","陕西"],"growth_stages_text":"① 幼苗期：三出复叶、小叶倒卵形有齿；② 蔓生期：茎匍匐或上升、多分枝；③ 开花期：花黄色、蝶形、2～5朵聚生；④ 结实期：荚果螺旋状卷曲、边缘有刺（是识别关键）。","best_control_stage_text":"幼苗期至蔓生初期。南苜蓿既可作绿肥也可成为麦田杂草，须根据用途决定防除时机。","spray_window_text":"麦田返青期处理；作为绿肥则保留翻压；果园与草坪早期处理。","identification_key_text":"三出复叶、小叶倒卵形、先端微凹、边缘有细齿；荚果呈螺旋状卷曲、边缘有刺（最典型识别特征）；花黄色蝶形。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":166,"cell_range":"A166:I166","row_sha256":"e89644d3255c46ad7e5e746f4e7e86c87b2a6ecb93b2694f9f72d8726b9030da","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=166;cells=A166:I166"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('9987ea28-6082-54d7-b2b2-8e12375d41cd'::uuid, 'e75df1d1-870a-5e29-96f3-f09028e44491'::uuid, 1, '浙江适用杂草：酢浆草', '{"kind":"weed","item_id":"zj-weed-r168","weed_name":"酢浆草","canonical_name":"酢浆草","scientific_name":"Oxalis corniculata","family_genus":"酢浆草科·酢浆草属","companion_crops":["蔬菜","果园","茶园","草坪","花卉苗圃"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","贵州","陕西","辽宁","台湾"],"growth_stages_text":"① 幼苗期：三出复叶、小叶心形；② 蔓延期：茎匍匐蔓延、节上生根；③ 开花期：花黄色、5瓣；④ 结实期：蒴果圆柱形、成熟后开裂弹出种子（弹射传播）。","best_control_stage_text":"幼苗期至蔓延前期。酢浆草匍匐茎节上生根、且蒴果弹射传播种子，须在蔓延和结实前处理。","spray_window_text":"蔬菜田、果园、茶园与草坪早期处理；结合清除覆盖物；花圃中须连根清除。","identification_key_text":"三出复叶、小叶倒心形（形似「三叶草」，是识别捷径）；茎匍匐、节上生根；花黄色5瓣；蒴果成熟后开裂、种子被弹射到远处。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":168,"cell_range":"A168:I168","row_sha256":"6df07f8e541d43afe7d36dc94c18a6063fdba4ee48fbb8ca102a7a82e4e2667d","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=168;cells=A168:I168"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('a4aba969-45af-512e-9c79-59bd7b2132dd'::uuid, '5ce6cb71-d3c0-5ff1-b277-22b4d8520f62'::uuid, 1, '浙江适用杂草：紫花酢浆草（红花酢浆草）', '{"kind":"weed","item_id":"zj-weed-r169","weed_name":"紫花酢浆草（红花酢浆草）","canonical_name":"紫花酢浆草","scientific_name":"Oxalis corymbosa","family_genus":"酢浆草科·酢浆草属","companion_crops":["果园","茶园","草坪","花卉苗圃","蔬菜"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","福建","广东","广西","四川","云南","贵州","台湾"],"growth_stages_text":"① 鳞茎期：地下具多数小鳞茎、是主要繁殖器官；② 幼苗期：三出复叶、小叶心形；③ 开花期：花紫红色、5瓣、伞房花序；④ 越冬期：鳞茎在土中越冬、断离的小鳞茎即可萌发。","best_control_stage_text":"幼苗期，且必须连鳞茎一并挖除。紫花酢浆草以小鳞茎繁殖，仅拔除地上部分必然复发。","spray_window_text":"连根挖除（须清除全部小鳞茎）；草坪与果园可在幼苗期施药；连续多年防治。","identification_key_text":"地下具多数小鳞茎（须挖净，残鳞茎可再生）；三出复叶、小叶倒心形；花紫红色、5瓣、伞房花序、花明显大于酢浆草。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":169,"cell_range":"A169:I169","row_sha256":"98fece39997725dab677a8b336da6120f683cc6105d43f03b21fcfd4388be620","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=169;cells=A169:I169"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('7e85651e-049e-54b8-845a-bffa012c8c29'::uuid, '900af6e4-8fc9-5f11-86ed-d0a5a9206be1'::uuid, 1, '浙江适用杂草：蛇莓', '{"kind":"weed","item_id":"zj-weed-r170","weed_name":"蛇莓","canonical_name":"蛇莓","scientific_name":"Duchesnea indica","family_genus":"蔷薇科·蛇莓属","companion_crops":["果园","茶园","蔬菜","草坪","非耕地"],"distribution_note":"","distribution_provinces":["江苏","浙江","安徽","湖北","湖南","江西","福建","广东","广西","四川","云南","贵州","河南","山东","陕西","辽宁","台湾"],"growth_stages_text":"① 幼苗期：三出复叶、小叶有齿；② 蔓延期：茎匍匐蔓延、节上生根、形成草层；③ 开花期：花黄色、5瓣、单生；④ 结实期：聚合果球形、鲜红色、表面有小突起（形似草莓，故名「蛇莓」）。","best_control_stage_text":"幼苗期至蔓延前期。","spray_window_text":"果园、茶园与草坪早期处理；草坪中须连根清除。","identification_key_text":"聚合果球形、鲜红色、表面密生小突起（形似草莓但较小，是识别捷径）；花黄色5瓣、单生；三出复叶、小叶倒卵形有齿；茎匍匐、节上生根。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":170,"cell_range":"A170:I170","row_sha256":"55296ddf6fb70938735d6f5aec1aa7cf78cfe440cc90ca1172a66c3f0d56f97c","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=170;cells=A170:I170"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('e1c34920-a12d-5597-ad8e-45ef9a8e8ab1'::uuid, 'e1b7ce04-249f-5a5d-bdbf-2a90f32f2902'::uuid, 1, '浙江适用杂草：半夏（野生）', '{"kind":"weed","item_id":"zj-weed-r171","weed_name":"半夏（野生）","canonical_name":"半夏","scientific_name":"Pinellia ternata","family_genus":"天南星科·半夏属","companion_crops":["玉米","大豆","蔬菜","果园","中药材田"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","重庆","云南","贵州","陕西","山西","甘肃"],"growth_stages_text":"① 块茎期：地下具球形块茎、是主要繁殖器官；② 幼苗期：叶片三出复叶（幼苗期常为单叶）；③ 旺长期：株高15～40cm、叶柄长；④ 开花期：肉穗花序外包绿色佛焰苞；⑤ 越冬期：块茎越冬。","best_control_stage_text":"幼苗期至旺长前期。半夏全株有毒（含草酸钙针晶，接触皮肤瘙痒、误食中毒），防除作业必须做好防护。","spray_window_text":"幼苗期人工连根挖除（须挖净块茎）或施药；作业时戴手套口罩；中药材田与农田目标不同，须区分对待。","identification_key_text":"叶片为三出复叶（小叶3枚）、叶柄基部常有一珠芽；地下具球形块茎；肉穗花序外包绿色佛焰苞；全株有毒，接触后皮肤瘙痒。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":171,"cell_range":"A171:I171","row_sha256":"55c9f4772eda3b20fb36ebe221b07d8bccaa6da30ecc5d53efe087fa75ce1812","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=171;cells=A171:I171"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('99e40408-89c7-57f3-baba-67e16d4b2782'::uuid, '35d80554-b1fa-5d6d-a373-91b8f540ab91'::uuid, 1, '浙江适用杂草：龙葵（野海椒）', '{"kind":"weed","item_id":"zj-weed-r172","weed_name":"龙葵（野海椒）","canonical_name":"龙葵","scientific_name":"Solanum nigrum","family_genus":"茄科·茄属","companion_crops":["玉米","大豆","棉花","蔬菜","马铃薯","果园"],"distribution_note":"全国广布","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","重庆","云南","贵州","陕西","山西","甘肃","辽宁","吉林","黑龙江","新疆","台湾"],"growth_stages_text":"① 幼苗期：叶片卵形、边缘波状；② 旺长期：株高30～100cm、茎直立多分枝；③ 开花期：花小、白色、5瓣、下垂、聚伞花序；④ 结实期：浆果球形、成熟后紫黑色、有光泽（形似小葡萄）。","best_control_stage_text":"幼苗期至旺长前期。龙葵浆果含龙葵碱有毒，且是马铃薯、番茄等茄科作物病虫害的中间寄主。","spray_window_text":"玉米、大豆、棉花田苗前封闭加苗后早期处理；蔬菜与马铃薯田注意选药（同为茄科）；须在结实前清除。","identification_key_text":"浆果球形、成熟后紫黑色有光泽（形似小葡萄，是识别捷径）；花小、白色5瓣、下垂；叶片卵形、边缘波状齿；幼苗期叶片上常带紫色。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":172,"cell_range":"A172:I172","row_sha256":"656675a927d11bbacda4312072a8e2a36048ed299043d03b7ac0d974ecc0b3df","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=172;cells=A172:I172"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('fd61a05c-8a71-56aa-808a-e2f813863302'::uuid, '29b9e0a1-6791-5d62-83d9-fe5cf70dad93'::uuid, 1, '浙江适用杂草：曼陀罗', '{"kind":"weed","item_id":"zj-weed-r173","weed_name":"曼陀罗","canonical_name":"曼陀罗","scientific_name":"Datura stramonium","family_genus":"茄科·曼陀罗属","companion_crops":["玉米","大豆","棉花","蔬菜","果园","非耕地"],"distribution_note":"","distribution_provinces":["河北","河南","山东","江苏","安徽","湖北","湖南","江西","浙江","福建","广东","广西","四川","云南","贵州","陕西","山西","甘肃","辽宁","吉林","黑龙江","新疆","内蒙古"],"growth_stages_text":"① 幼苗期：叶片卵形、边缘有粗齿；② 旺长期：株高0.5～2m、茎粗壮、多分枝；③ 开花期：花大型、白色或淡紫色、漏斗状、单生叶腋；④ 结实期：蒴果卵球形、表面密生坚硬针刺（形似小刺球）、成熟后4瓣开裂。","best_control_stage_text":"幼苗期至旺长前期。曼陀罗全株有毒（含莨菪碱等，误食可致中毒甚至死亡），防除与收获时必须严防混入农产品。","spray_window_text":"幼苗期人工连根拔除或施药；作业时戴手套；开花前必须清除；严禁茎叶混入饲料或农产品；收获时注意清除。","identification_key_text":"花大型、白色或淡紫色、漏斗状（形如喇叭）；蒴果卵球形、表面密生坚硬针刺（形似小刺球，是最直观识别特征）；全株有特殊臭味、有毒。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":173,"cell_range":"A173:I173","row_sha256":"0d3c309ecd59bc6130cdf1019fac524c8c5d1c560a7a9c968598f5bcfd8f7bfb","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=173;cells=A173:I173"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_corn","crop_soybean"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('09e67673-0841-5f03-9eb9-126cf9b0c32c'::uuid, '1fd96b2a-331a-5652-8ae3-e1304ff77d3b'::uuid, 1, '浙江适用杂草：假臭草', '{"kind":"weed","item_id":"zj-weed-r175","weed_name":"假臭草","canonical_name":"假臭草","scientific_name":"Praxelis clematidea","family_genus":"菊科·假臭草属","companion_crops":["果园","甘蔗","蔬菜","非耕地","路边"],"distribution_note":"","distribution_provinces":["广东","广西","海南","福建","云南","江西","湖南","浙江","台湾"],"growth_stages_text":"① 幼苗期：叶片对生、卵形有齿；② 旺长期：株高30～100cm、茎直立多分枝；③ 开花期：头状花序小、淡紫色、密集成伞房状；④ 结实期：种子带冠毛、随风传播。","best_control_stage_text":"幼苗期至旺长前期。假臭草全株有强烈臭味、繁殖快，须在开花前清除。","spray_window_text":"甘蔗田、果园与蔬菜田早期处理；开花前清除；连续多年监测。","identification_key_text":"全株有强烈臭味（揉碎后气味刺鼻，故名「假臭草」）；头状花序小、淡紫色、密集成伞房状；叶片对生、卵形、边缘有粗齿、基部有3条主脉。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":175,"cell_range":"A175:I175","row_sha256":"acdfb834605e0b40809c8147837b90001264b250f2e2cb595f578b950b175910","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=175;cells=A175:I175"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('945f5459-cc72-5ed2-a8ec-ff8417155320'::uuid, 'aeb17cc5-dff5-5096-8ef5-74a21136d499'::uuid, 1, '浙江适用杂草：杂草稻（野稻）', '{"kind":"weed","item_id":"zj-weed-r176","weed_name":"杂草稻（野稻）","canonical_name":"杂草稻","scientific_name":"Oryza sativa f. spontanea","family_genus":"禾本科·稻属","companion_crops":["水稻（稻田中）"],"distribution_note":"","distribution_provinces":["黑龙江","吉林","辽宁","江苏","浙江","安徽","江西","湖北","湖南","广东","广西","福建","海南","四川","重庆","贵州","云南","河南","山东","台湾"],"growth_stages_text":"① 幼苗期：与栽培稻幼苗几乎无法区分；② 分蘖期：分蘖力强、株型较散；③ 抽穗期：抽穗早于或与栽培稻同期、穗型松散、芒长、易落粒；④ 成熟期：种子随熟随落、落粒性极强，形成土壤种子库。","best_control_stage_text":"分蘖期之前（株高20cm以内）。杂草稻与水稻同属，选择性药剂极少，主要依靠「拔除」与农艺措施；一旦落粒形成种子库将长期危害。","spray_window_text":"移栽前整地时清理；分蘖期人工拔除（须在抽穗前完成，连根拔除并带出田外销毁）；水旱轮作；种子清选；苗期可用部分专用药剂。","identification_key_text":"与栽培稻极相似，区别要点：杂草稻抽穗早、穗型松散、谷粒易落（轻触即落）、多有长芒、株型较散、部分类型苗期叶片带红色；落粒性是田间最实用的判断依据。","zhejiang_evidence_strength":"distribution_field","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"杂草总表","excel_row":176,"cell_range":"A176:I176","row_sha256":"b104906ba29483542863686447c85021affef401cf4c3b541e3978af1d42c742","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=杂草总表;row=176;cells=A176:I176"}}', 'species', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('a59f2551-05aa-53ca-a49c-28de9aea2398'::uuid, 'ff439e11-0ba5-5256-aba5-fe245ac4a521'::uuid, 1, '浙江防除时期：水稻（移栽田）', '{"kind":"control_timing","item_id":"zj-timing-r2","scene_text":"水稻（移栽田）","critical_window_text":"移栽后5～15天（杂草幼苗期）","target_weeds_text":"稗草、异型莎草、鸭舌草、牛毛毡、矮慈姑、眼子菜、水绵","key_points_text":"以土壤封闭为主，趁杂草未出土或刚出土时施药；保水层3～5cm，保水5～7天。","zhejiang_scope_basis":"场景作物与省份索引表浙江行（r12）主要作物一致：水稻","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"防除时期速查","excel_row":2,"cell_range":"A2:D2","row_sha256":"9c5e0c2f1a7ed254c03805a52e6fe137c669addb7a097191f330bde06890886f","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=防除时期速查;row=2;cells=A2:D2"}}', 'scheme', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('d361a7b1-f44e-528d-86c6-c54320a9c708'::uuid, '5cfaca83-4134-54f5-909b-1ccbb4bf81e2'::uuid, 1, '浙江防除时期：水稻（直播田）', '{"kind":"control_timing","item_id":"zj-timing-r3","scene_text":"水稻（直播田）","critical_window_text":"播后2～4天封闭＋稗草2～3叶期","target_weeds_text":"稗草、千金子、杂草稻、异型莎草、鸭舌草、节节菜","key_points_text":"直播田杂草出苗早、密度高，必须「一封一杀」；千金子抽穗极早，须抢在抽穗前。","zhejiang_scope_basis":"场景作物与省份索引表浙江行（r12）主要作物一致：水稻","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"防除时期速查","excel_row":3,"cell_range":"A3:D3","row_sha256":"6139ae745169b0bdde2af12d1d0736d6886973bda86feaf85b19127df01cc5ce","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=防除时期速查;row=3;cells=A3:D3"}}', 'scheme', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rice"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('fd2a3c63-e62e-55fb-a379-d6f320f54f6b'::uuid, 'a238e919-5221-5c8e-bc3e-57731b2d7cd8'::uuid, 1, '浙江防除时期：油菜', '{"kind":"control_timing","item_id":"zj-timing-r9","scene_text":"油菜","critical_window_text":"播后苗前封闭＋苗后早期（越冬前）","target_weeds_text":"看麦娘、日本看麦娘、繁缕、牛繁缕、猪殃殃、播娘蒿、荠菜、大巢菜","key_points_text":"油菜为阔叶作物，选药须严格，避免药害；禾本科杂草用选择性药剂。","zhejiang_scope_basis":"场景作物与省份索引表浙江行（r12）主要作物一致：油菜","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"防除时期速查","excel_row":9,"cell_range":"A9:D9","row_sha256":"c0a5abe8cc78c641deb0eb80a30575f06bf814557794db8dcc1a934bcc72ba67","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=防除时期速查;row=9;cells=A9:D9"}}', 'scheme', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '["crop_rapeseed"]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('db463f04-cab5-5029-8fa9-0a1476f9c894'::uuid, '3116961f-7ba7-5b94-84a0-2bb3bc5a330b'::uuid, 1, '浙江防除时期：蔬菜', '{"kind":"control_timing","item_id":"zj-timing-r10","scene_text":"蔬菜","critical_window_text":"播后苗前封闭＋定植前土壤处理","target_weeds_text":"马齿苋、反枝苋、藜、苋、马唐、牛筋草、繁缕、酢浆草","key_points_text":"蔬菜种类多、安全性差异大，须按具体作物选药；采收前注意安全间隔期。","zhejiang_scope_basis":"场景作物与省份索引表浙江行（r12）主要作物一致：蔬菜","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"防除时期速查","excel_row":10,"cell_range":"A10:D10","row_sha256":"dbaafb577e152e82f9b103b785f5a8fa4d12285b96257d80db29890cfe40b20d","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=防除时期速查;row=10;cells=A10:D10"}}', 'scheme', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('26ee2b8f-4226-5a28-be55-f4e786fa196b'::uuid, '08c5d805-89dc-5fc2-8e08-2bfc34aab921'::uuid, 1, '浙江防除时期：果园／茶园', '{"kind":"control_timing","item_id":"zj-timing-r11","scene_text":"果园／茶园","critical_window_text":"春季返青期＋杂草蔓延前期（连续2～3次）","target_weeds_text":"白茅、狗牙根、香附子、双穗雀稗、小蓬草、胜红蓟、葎草、问荆","key_points_text":"多年生深根杂草须「灭生性药剂＋深翻」结合，间隔30～45天重复；避开树冠与水源。","zhejiang_scope_basis":"场景作物与省份索引表浙江行（r12）主要作物一致：茶园、果园","dose_text":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_weed_summary_workbook","source_version":"weed-summary-2026.10","file":"中国各省份农田常见杂草识别与防除时期汇总表.xlsx","file_sha256":"e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420","sheet":"防除时期速查","excel_row":11,"cell_range":"A11:D11","row_sha256":"bef80e0d5d1b626ef3a9fe884859b4ff0503cd606a38f4ab5b33857948238a18","locator":"file=中国各省份农田常见杂草识别与防除时期汇总表.xlsx;sha256=e708577e1cd035b435686c8d249209aa96d345d86a33a9a870e01cd6cdddc420;sheet=防除时期速查;row=11;cells=A11:D11"}}', 'scheme', 'e85622e0-d53b-573b-a326-ce32cd387dc8'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('9aac1edc-cd6a-509d-80e7-3880e9a8c7bd'::uuid, '798405ed-e98f-5a3f-84e9-9c871ea2ce77'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：草甘膦', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r3","herbicide_name":"草甘膦","aliases_text":"农达、镇草宁、草干膦、膦甘酸、Roundup","hazard_level_text":"高危","hazard_detail_text":"水溶性高、不易降解，常在地表水和地下水中检出；对两栖类有内分泌干扰与致畸风险，被IARC列为2A类可能致癌物；长期单一使用导致牛筋草、小飞蓬等抗性杂草暴发；欧盟已不再批准其有效成分。","target_weeds_text":"灭生性内吸传导型：一年生及多年生禾本科、莎草科和阔叶杂草，对白茅、香附子、狗牙根、芦苇等深根性杂草有效。","region_text":"全球用量最大除草剂，中国各地均有使用；华南、长江中下游、西南的果园、茶园、橡胶园及铁路公路沿线最集中；欧盟、越南、斯里兰卡等已禁用或限制。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":3,"cell_range":"A3:F3","row_sha256":"bef70cdd605cb8484b49ff0b050d35d5fd9896271b11f0d2ee6105149c3e8d95","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=3;cells=A3:F3"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('d1a988ff-5f7e-5498-a5f5-b440acd714c4'::uuid, '18f53a98-8b5b-5b0f-8022-09c275efbd43'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：灭草松', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r14","herbicide_name":"灭草松","aliases_text":"排草丹、苯达松、噻草平、Basagran","hazard_level_text":"高危","hazard_detail_text":"水溶性高，极易淋溶污染地下水，是欧洲地下水监测中检出最频繁的除草剂之一；对水生植物毒性较高。","target_weeds_text":"苗后防除阔叶杂草与莎草：鸭舌草、异型莎草、碎米莎草、苋、藜、蓼、苍耳等。","region_text":"中国水稻区（长江中下游、华南、东北）及大豆、花生区；欧盟多国已限制使用。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":14,"cell_range":"A14:F14","row_sha256":"37e1306b2a3ba201d43287d21b222e61321d4d17438c9b8e0ba75bb3ae0e1bf6","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=14;cells=A14:F14"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('ddf25d77-084b-5c9e-9ce4-77120bb6ee11'::uuid, '5a0c7d07-e9ce-5a4a-bf49-d8eff8682a2c'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：异丙隆', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r18","herbicide_name":"异丙隆","aliases_text":"异丙隆可湿性粉剂、Arelon、Tolkan","hazard_level_text":"高危","hazard_detail_text":"水溶性高，是欧洲地下水检出最频繁的除草剂之一，欧盟已不再批准；对水生植物有毒。","target_weeds_text":"小麦、大麦田防除看麦娘、日本看麦娘、硬草、早熟禾、播娘蒿、荠菜等。","region_text":"中国长江中下游与黄淮麦区（江苏、安徽、湖北、河南、山东）；欧盟禁用。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":18,"cell_range":"A18:F18","row_sha256":"993c927fb571990530e041b7dcd1ea231ad3207ef8b984de3a87868225869649","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=18;cells=A18:F18"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('92d03f41-00f0-5aec-8423-bdcc9a7de770'::uuid, '058c72fb-5f09-574a-9f5b-c0e22d25bc3f'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：烯草酮', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r29","herbicide_name":"烯草酮","aliases_text":"收乐通、赛乐特、Select、Selectone","hazard_level_text":"低危","hazard_detail_text":"低毒，对哺乳动物和蜜蜂安全；土壤降解快，对地下水风险小；对鱼类中等毒性。","target_weeds_text":"苗后防除禾本科杂草：稗草、马唐、狗尾草、牛筋草、看麦娘、野燕麦、狗牙根、白茅等，对阔叶作物安全。","region_text":"中国大豆、花生、油菜、棉花、蔬菜田（东北、黄淮海、长江流域）。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":29,"cell_range":"A29:F29","row_sha256":"a28f4ce48c05e878a20324e43167224f09dc7770fbdbbeb37785ca2aa97bca75","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=29;cells=A29:F29"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('1db80181-f199-544b-87ee-a6093c78de11'::uuid, '683824bc-6e0b-5ef4-87a7-d42a2d30bc35'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：精喹禾灵', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r30","herbicide_name":"精喹禾灵","aliases_text":"禾草克、精禾草克、Assure","hazard_level_text":"低危","hazard_detail_text":"低毒，土壤降解快，不易淋溶；对水生生物中等毒性，飘移对禾本科作物有药害风险。","target_weeds_text":"苗后防除一年生及多年生禾本科杂草：稗草、马唐、狗尾草、牛筋草、白茅、芦苇、狗牙根等。","region_text":"中国大豆、花生、油菜、棉花、蔬菜与果园（东北、黄淮海、长江中下游）。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":30,"cell_range":"A30:F30","row_sha256":"f6c6dbd188a07959fecebfa9baed1160aebd8ff38bb9dcc2b652208e5ed2dbd3","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=30;cells=A30:F30"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('00de6753-aed1-5112-ae87-3544d8b25609'::uuid, 'b876dafc-a82e-57fd-b0ad-5697fd82f7ce'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：高效氟吡甲禾灵', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r32","herbicide_name":"高效氟吡甲禾灵","aliases_text":"盖草能、高效盖草能、Gallant","hazard_level_text":"低危","hazard_detail_text":"低毒，土壤降解快，残留风险低；对鱼类中等毒性，需避开水源施药。","target_weeds_text":"苗后防除禾本科杂草：马唐、牛筋草、狗尾草、稗草、狗牙根、白茅、芦苇等。","region_text":"中国油菜、大豆、花生、棉花、蔬菜及果园（长江流域、黄淮海、华南）。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":32,"cell_range":"A32:F32","row_sha256":"626a51c58f2b798634bf8d857ec7c13db84013a340b110626db93bc2eb21f0b7","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=32;cells=A32:F32"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
