INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('318c9cc3-ed78-55df-9c07-9abc7acf4ff5'::uuid, '22231bac-d015-5d29-bcb4-f7d1c30cf355'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：精噁唑禾草灵', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r36","herbicide_name":"精噁唑禾草灵","aliases_text":"骠马、威霸、Puma、Whip","hazard_level_text":"低危","hazard_detail_text":"低毒；土壤降解较快；对水生生物中等毒性，需注意稻田排水。","target_weeds_text":"小麦、大豆、油菜、蔬菜田防除禾本科杂草：野燕麦、看麦娘、马唐、稗草、狗尾草、牛筋草。","region_text":"中国华北、黄淮、长江中下游麦区及大豆、油菜、蔬菜区。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":36,"cell_range":"A36:F36","row_sha256":"6afa83cf8656baff59fe0e279b7e6c815f0873b8c45112bc5a798f6b616d343f","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=36;cells=A36:F36"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('01b52ae7-237c-5618-98d7-ebcb14565bc9'::uuid, '1381a271-03fb-5cd3-a780-0ef661e842ed'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：敌稗', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r38","herbicide_name":"敌稗","aliases_text":"斯达姆、Stam、敌稗乳油","hazard_level_text":"低危","hazard_detail_text":"中等毒性，对鱼类和甲壳类毒性较高；稻田水中降解较快，但代谢物3,4-二氯苯胺有一定环境风险。","target_weeds_text":"稻田苗后防除稗草、异型莎草、鸭舌草、牛毛毡等。","region_text":"中国南方稻区（长江中下游、华南、西南）；美国、意大利等水稻区也用。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":38,"cell_range":"A38:F38","row_sha256":"5cb1b573282fa6844e01e4953ff5f25e7bc3753471462e17f4b2f4c3a86e23bb","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=38;cells=A38:F38"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('c527bb3b-2520-5f8d-b415-40ef5cf8bdf7'::uuid, '6f631132-5986-560a-873f-3f27a4ec210b'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：丁草胺', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r39","herbicide_name":"丁草胺","aliases_text":"马歇特、去草胺、灭草特、Machete","hazard_level_text":"低危","hazard_detail_text":"低至中等毒性，对鱼类毒性较高；土壤中降解较快，但对稻田水生生物和藻类有影响。","target_weeds_text":"稻田芽前封闭：稗草、牛毛毡、异型莎草、鸭舌草、千金子、水苋菜等。","region_text":"中国各稻区（长江中下游、华南、西南、东北）。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":39,"cell_range":"A39:F39","row_sha256":"70a809031a8aa71b4ebc589f72e4ba12e348d9705cd2e6e98ad1ae778ed616c6","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=39;cells=A39:F39"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('2744bdd2-1019-5076-a8e4-f8b89c7f764c'::uuid, '7dccb6e8-5c21-5db3-bfaf-c6d75fc73e04'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：丙草胺', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r40","herbicide_name":"丙草胺","aliases_text":"扫弗特、瑞飞特、Softit、Rifit","hazard_level_text":"低危","hazard_detail_text":"低毒，对哺乳动物安全；对鱼类中等毒性，降解较快，残留低。","target_weeds_text":"直播稻与移栽稻田芽前封闭：稗草、千金子、异型莎草、鸭舌草、牛毛毡等。","region_text":"中国长江中下游直播稻区（江苏、安徽、湖北、湖南、江西、浙江）。","zhejiang_evidence":"zhejiang_explicit","zhejiang_basis":"适用／常用地区字段直接列出「浙江」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":40,"cell_range":"A40:F40","row_sha256":"c1caa14031a554ac43efdabbe3fdeb1d916387ea18c5ac0a901edad38b506f2c","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=40;cells=A40:F40"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('721b95fd-a028-57f2-b67d-322d487059bd'::uuid, '4757166a-aef1-5f9d-b6d6-bc5f9d1abe40'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：敌草胺', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r44","herbicide_name":"敌草胺","aliases_text":"大惠利、萘丙酰草胺、Devrinol","hazard_level_text":"低危","hazard_detail_text":"低毒；水溶性中等，对地下水有潜在风险；对水生生物中等毒性；土壤降解中等。","target_weeds_text":"蔬菜、果园、油菜、烟草田芽前防除一年生禾本科与阔叶杂草：马唐、稗草、藜、苋、马齿苋。","region_text":"中国华东、华中、华南蔬菜基地与果园（江苏、浙江、湖北、湖南、广东）。","zhejiang_evidence":"zhejiang_explicit","zhejiang_basis":"适用／常用地区字段直接列出「浙江」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":44,"cell_range":"A44:F44","row_sha256":"0ca74e6884e1cae21ada2a57b854a9cfa5c332e7c62c3c151c56243bcbda701f","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=44;cells=A44:F44"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('72bea752-69b0-51f3-bcb2-b5aa4b181c54'::uuid, '1dc3926d-4f01-58e0-9f26-d90c53def082'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：乙氧氟草醚', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r47","herbicide_name":"乙氧氟草醚","aliases_text":"果尔、割地草、Goal","hazard_level_text":"低危","hazard_detail_text":"中等毒性，对鱼类及水生生物高毒，需远离水体；土壤中降解较慢，持效期长。","target_weeds_text":"芽前与苗后早期防除阔叶及禾本科杂草：稗草、异型莎草、鸭舌草、藜、苋、马齿苋，用于稻田、果园、蔬菜。","region_text":"中国南方稻区（长江中下游、华南）及果园、蔬菜基地。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":47,"cell_range":"A47:F47","row_sha256":"48fc8587ab0ce692684cabddb217c9aa8e2a9e98e049a70299d149d3a48de7dc","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=47;cells=A47:F47"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
