INSERT INTO knowledge_versions (id, knowledge_id, revision, title, body, type, source_version_id, crop_ids, species_ids, region_codes, visibility) VALUES ('970bf9a0-954f-5181-bed4-2d0b423ac483'::uuid, '6fb50221-c485-5b84-895d-0414792a4bb8'::uuid, 1, '浙江适用除草剂（环境风险与适用信息）：唑草酮', '{"kind":"herbicide_applicability","item_id":"zj-herbicide-r55","herbicide_name":"唑草酮","aliases_text":"快灭灵、Aim、Affinity","hazard_level_text":"低危","hazard_detail_text":"低毒、用量低；对水生生物中等毒性；土壤降解较快，残留风险小。","target_weeds_text":"小麦、玉米田苗后防除阔叶杂草：播娘蒿、荠菜、藜、苋、猪殃殃、田旋花等。","region_text":"中国华北、黄淮、长江中下游小麦区（河北、河南、山东、安徽、江苏）。","zhejiang_evidence":"yangtze_mid_lower_xref","zhejiang_basis":"字段含「长江中下游/长江流域」；省份索引表浙江行（r12）所属大区即「长江中下游稻区」","dose_text":null,"dose_status":"absent_in_source","application_method_text":null,"precautions_text":null,"registration_number":null,"usable_as_dose":false,"card_ready":false,"provenance":{"source_id":"src_gengyun_herbicide_risk_workbook","source_version":"herbicide-risk-2026.10","file":"市面常见除草剂环境风险与适用信息汇总表.xlsx","file_sha256":"c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70","sheet":"除草剂汇总表","excel_row":55,"cell_range":"A55:F55","row_sha256":"5bebdc918aae2e9db5092295156a6e08187954606f71c7e42459fff597880282","locator":"file=市面常见除草剂环境风险与适用信息汇总表.xlsx;sha256=c4905d850b3750c712b10fd8278b5029448a651308fb92c186df604a527c9e70;sheet=除草剂汇总表;row=55;cells=A55:F55"}}', 'herbicide', '0a9deb7e-45e0-5752-b07e-5a5da62f3599'::uuid, '[]'::jsonb, '[]'::jsonb, '["330000"]'::jsonb, 'private') ON CONFLICT (id) DO NOTHING;
